DO $acai$
DECLARE
 j constant jsonb := $records$[{"id":"c9b69094-9cd5-4b3c-b33b-a988f326b009","recipe_group_id":"b6b4397e-f51a-4c05-bf7a-fa285432829b","slug":"acai-bowl","public_path":"/acai-bowl","source_url":"https://manualdecocina.com/acai-bowl/","language":"es","title":"Açaí bowl con plátano, fresas y granola","excerpt":"Base espesa de açaí y plátano congelado con cobertura medida de fruta, granola y almendras. Dos cuencos propuestos y nutrición estimada por ración.","summary":"Base fría de açaí sin azúcar y plátano congelado, con fresas, granola y almendras. Se proponen dos cuencos para comer con cuchara, no un zumo, y 135 minutos incluyendo la congelación previa del plátano. Fórmula y tiempos pendientes de prueba de cocina.","category":"Postres","category_slug":"postres","difficulty":"Fácil","course":"Desayuno o postre","cuisine":"Inspiración brasileña","prep_time_minutes":15,"cook_time_minutes":0,"total_time_minutes":135,"servings":2,"ingredients":[{"name":"pulpa de açaí congelada sin azúcar, lista para consumo","amount":"200","unit":"g","group":"Base"},{"name":"plátano maduro sin piel, para congelar","amount":"160","unit":"g","group":"Base"},{"name":"agua potable fría","amount":"60","unit":"g","group":"Base"},{"name":"plátano maduro fresco sin piel","amount":"60","unit":"g","group":"Cobertura"},{"name":"fresas frescas, sin pedúnculo","amount":"100","unit":"g","group":"Cobertura"},{"name":"granola lista para comer","amount":"40","unit":"g","group":"Cobertura"},{"name":"almendras naturales laminadas","amount":"20","unit":"g","group":"Cobertura"}],"steps":[{"title":"Congela el plátano de la base","content":"Lávate las manos y enjuaga el plátano antes de pelarlo. Pesa 160 g de pulpa madura y corta en rodajas de 1 cm. Extiéndelas separadas sobre una bandeja limpia y congela a −18 °C o menos durante 120 minutos como referencia, hasta que estén duras; si no lo están, prolonga y registra el tiempo real. Reserva aparte el plátano fresco de la cobertura. Los 120 minutos de congelación forman parte de los 135 minutos totales propuestos. Si ya tienes esos 160 g congelados, el montaje se estima en 15 minutos.","image_url":"/recetas/acai-bowl/paso-01.webp","image_alt":"Açaí bowl: Congela el plátano de la base"},{"title":"Prepara la cobertura y el equipo","content":"Mientras el plátano termina de congelarse, enjuaga las fresas bajo agua corriente, sin jabón, sécalas, retira los pedúnculos y pesa 100 g; córtalas en láminas. Pela y corta 60 g de plátano fresco, y pesa 40 g de granola lista para comer y 20 g de almendras laminadas. Mide 60 g de agua potable fría. Usa dos cuencos de unos 400 ml y una batidora apta para fruta congelada según su manual; mantén fría la fruta cortada hasta el montaje.","image_url":"/recetas/acai-bowl/paso-02.webp","image_alt":"Açaí bowl: Prepara la cobertura y el equipo"},{"title":"Trocea la pulpa congelada de açaí","content":"Comprueba que la pulpa sea sin azúcar y esté indicada para consumo directo; esta receta no sustituye una cocción exigida por la etiqueta. Saca 200 g del congelador justo antes de batir. Flexiona los paquetes cerrados para partir la pulpa o deja correr agua sobre el exterior unos 20 segundos para aflojarla, sin descongelarla del todo. Seca el envase, ábrelo por la zona indicada y vuelca los trozos en un cuenco limpio. Usa cuchillo o tijeras con cuidado y evita fragmentos de plástico; no cortes hacia la mano.","image_url":"/recetas/acai-bowl/paso-03.webp","image_alt":"Açaí bowl: Trocea la pulpa congelada de açaí"},{"title":"Tritura una base espesa","content":"Pon primero los 60 g de agua en el vaso y después los 160 g de plátano congelado y los 200 g de açaí troceado, respetando las instrucciones y capacidad de tu batidora. Cierra la tapa y pulsa en intervalos cortos; tritura aproximadamente 1 minuto en total hasta obtener una crema morada espesa, sin grandes trozos. Si hace falta, apaga y desenchufa antes de bajar la mezcla con espátula; nunca introduzcas utensilios o manos mientras las cuchillas giran. No fuerces el motor: si no puede moverla, deja ablandar unos minutos. Agua adicional cambia la consistencia y el peso de referencia.","image_url":"/recetas/acai-bowl/paso-04.webp","image_alt":"Açaí bowl: Tritura una base espesa"},{"title":"Reparte la crema en dos cuencos","content":"Con las cuchillas detenidas, reparte toda la base entre los dos cuencos, aproximadamente 210 g en cada uno antes de la cobertura, según lo que se recupere del vaso. Alisa suavemente con una cuchara. Debe sostener la fruta en la superficie y comerse con cuchara; si queda muy líquida, enfría unos minutos en el congelador y registra ese tiempo extra. No añadas hielo para ocultar un exceso de agua.","image_url":"/recetas/acai-bowl/paso-05.webp","image_alt":"Açaí bowl: Reparte la crema en dos cuencos"},{"title":"Añade la cobertura y sirve enseguida","content":"Pon en cada cuenco 30 g de plátano fresco, 50 g de fresas, 20 g de granola y 10 g de almendras laminadas. Forma franjas dejando visible parte de la base morada. Sirve de inmediato: se proponen 2 cuencos de unos 320 g, con 15 minutos de trabajo y 120 de congelación previa, sin cocción. Cantidades, textura, tiempos y rendimiento son estimados y pendientes de prueba de cocina; las calorías incluyen toda la cobertura indicada.","image_url":"/recetas/acai-bowl/portada.webp","image_alt":"Açaí bowl: Añade la cobertura y sirve enseguida"}],"nutrition":{"calories":339.6,"protein_g":7.4,"carbs_g":45.9,"fat_g":15.4,"saturated_fat_g":2.3,"fiber_g":9.9,"sugar_g":20.3,"sodium_mg":18,"estimated":true,"source":"USDA FoodData Central — SR Legacy y Branded","source_url":"https://fdc.nal.usda.gov/download-datasets/","inputs":[{"ingredient":"pulpa de açaí congelada sin azúcar, lista para consumo","edible_grams":200,"fdc_id":2653289,"fdc_description":"ZERO SUGAR PURE UNSWEETENED AA BERRY SUPERFRUIT PACKS, AA BERRY","per_100g":{"calories":70,"protein_g":1,"carbs_g":4,"fat_g":5,"saturated_fat_g":1,"fiber_g":3,"sugar_g":0,"sodium_mg":10},"source_url":"https://fdc.nal.usda.gov/food-details/2653289/nutrients"},{"ingredient":"plátano maduro sin piel, para congelar","edible_grams":160,"fdc_id":173944,"fdc_description":"Bananas, raw","per_100g":{"calories":89,"protein_g":1.09,"carbs_g":22.8,"fat_g":0.33,"saturated_fat_g":0.112,"fiber_g":2.6,"sugar_g":12.2,"sodium_mg":1},"source_url":"https://fdc.nal.usda.gov/food-details/173944/nutrients"},{"ingredient":"agua potable fría","edible_grams":60,"fdc_id":173647,"fdc_description":"Beverages, water, tap, drinking","per_100g":{"calories":0,"protein_g":0,"carbs_g":0,"fat_g":0,"saturated_fat_g":0,"fiber_g":0,"sugar_g":0,"sodium_mg":4},"source_url":"https://fdc.nal.usda.gov/food-details/173647/nutrients"},{"ingredient":"plátano maduro fresco sin piel","edible_grams":60,"fdc_id":173944,"fdc_description":"Bananas, raw","per_100g":{"calories":89,"protein_g":1.09,"carbs_g":22.8,"fat_g":0.33,"saturated_fat_g":0.112,"fiber_g":2.6,"sugar_g":12.2,"sodium_mg":1},"source_url":"https://fdc.nal.usda.gov/food-details/173944/nutrients"},{"ingredient":"fresas frescas, sin pedúnculo","edible_grams":100,"fdc_id":167762,"fdc_description":"Strawberries, raw","per_100g":{"calories":32,"protein_g":0.67,"carbs_g":7.68,"fat_g":0.3,"saturated_fat_g":0.015,"fiber_g":2,"sugar_g":4.89,"sodium_mg":1},"source_url":"https://fdc.nal.usda.gov/food-details/167762/nutrients"},{"ingredient":"granola lista para comer","edible_grams":40,"fdc_id":171646,"fdc_description":"Cereals ready-to-eat, granola, homemade","per_100g":{"calories":489,"protein_g":13.7,"carbs_g":53.9,"fat_g":24.3,"saturated_fat_g":3.96,"fiber_g":8.9,"sugar_g":19.8,"sodium_mg":26},"source_url":"https://fdc.nal.usda.gov/food-details/171646/nutrients"},{"ingredient":"almendras naturales laminadas","edible_grams":20,"fdc_id":170567,"fdc_description":"Nuts, almonds","per_100g":{"calories":579,"protein_g":21.2,"carbs_g":21.6,"fat_g":49.9,"saturated_fat_g":3.8,"fiber_g":12.5,"sugar_g":4.35,"sodium_mg":1},"source_url":"https://fdc.nal.usda.gov/food-details/170567/nutrients"}],"serving_size":"Un cuenco; 2 raciones de unos320 g propuestas, sin peso final medido","method":"Suma siete cantidades comestibles en gramos por sus ocho valores USDA por100 g y divide entre2. Plátano de base y cobertura se calculan por separado con la misma ficha. Incluye60 g de agua y toda la granola y almendras. No inventa pérdidas por congelación o triturado.","note":"Estimación de ingredientes, no análisis ni prueba de cocina. Pulpa comercial sin azúcar modelada con FDC2653289,Sambazon, ficha publicada2023-10-26; no representa todas las marcas ni açaí en polvo, bebida o sorbete. Granola genérica casera FDC171646 como referencia: azúcares, sodio y grasas varían por etiqueta. El agua se modela con la ficha potable FDC173647; sus minerales varían. Todos los nutrientes están presentes en las fichas; no se sustituyen ausencias por cero."},"image_url":"/recetas/acai-bowl/portada.webp","gallery":[{"url":"/recetas/acai-bowl/portada.webp","alt":"Dos cuencos de açaí morado espeso con plátano, fresas, granola y almendras laminadas en franjas"}],"published":true,"editorial_status":"published","keywords":["açaí bowl","bowl de açaí","açaí con plátano","açaí con granola"],"notes":"Cantidades y textura propuestas, sin prueba de cocina. El açaí debe ser pulpa congelada sin azúcar, apta para consumo directo según la etiqueta; sorbete, polvo, bebida o mezcla con guaraná y azúcar no son equivalentes. El plátano aporta dulzor; no se incorpora miel ni sirope. No se presenta el bowl como detox, adelgazante ni tratamiento. Lava la fruta bajo agua corriente antes de pelarla o cortarla; no uses jabón. Mantén la pulpa congelada hasta prepararla y respeta el manual de la batidora, apagándola y desenchufándola antes de tocar el interior. Sirve inmediatamente; como previsión doméstica no ensayada, guarda solo la base sobrante tapada a 4 °C o menos y consúmela en 24 horas, conservando la cobertura seca aparte. La textura pierde firmeza en frío; no se garantiza que recupere el resultado al volver a congelarla. No dejes alimentos perecederos más de 2 horas a temperatura ambiente, o 1 hora si supera 32 °C. Contiene almendras; granola y pulpa pueden contener otros frutos secos, gluten, soja o leche según la marca. Revisa etiquetas. Puedes sustituir las almendras por semillas si son apropiadas para tus comensales, o la granola por copos tostados listos para comer, pero cambia la nutrición. No sustituyas açaí por otra fruta y mantengas el mismo nombre de receta. La estimación usa una ficha USDA de pulpa comercial sin azúcar y granola genérica; la etiqueta real puede diferir.","seo":{"title":"Açaí bowl con plátano y granola paso a paso","description":"Prepara dos bowls de açaí espeso con plátano congelado, fresas y granola. Cantidades propuestas, congelación incluida y nutrición estimada.","image_alt":"Dos cuencos de açaí morado espeso con plátano, fresas, granola y almendras laminadas en franjas","image_variants":["/recetas/acai-bowl/portada-1x1.webp","/recetas/acai-bowl/portada-4x3.webp","/recetas/acai-bowl/portada-16x9.webp"],"faq":[{"q":"¿Qué açaí sirve para esta receta?","a":"Usa 200 g de pulpa congelada sin azúcar y apta para consumo directo, según la etiqueta. Sorbete, polvo y mezclas azucaradas no tienen la misma composición ni la misma textura. La nutrición publicada usa una ficha comercial USDA de referencia."},{"q":"¿Por qué queda líquido o no se mueve en la batidora?","a":"El plátano debe estar congelado y el açaí no debe descongelarse del todo. Se proponen 60 g de agua para toda la base; añadir más la diluye. Usa una batidora apta para congelados y no fuerces el motor. Apaga y desenchufa antes de bajar la mezcla; deja ablandar un poco si lo exige tu equipo."},{"q":"¿Cuánto tarda y puedo guardarlo?","a":"Se estiman 135 minutos: 120 para congelar160 g de plátano y15 de trabajo. Con plátano ya congelado, el montaje se estima en15 minutos. Sirve los dos cuencos enseguida; una base sobrante puede refrigerarse tapada a4 °C o menos y consumirse en24 horas como propuesta doméstica sin ensayo, con la cobertura aparte."}]},"content_html":"<p>Base fría de açaí sin azúcar y plátano congelado, con fresas, granola y almendras. Se proponen dos cuencos para comer con cuchara, no un zumo, y 135 minutos incluyendo la congelación previa del plátano. Fórmula y tiempos pendientes de prueba de cocina.</p><p>Cantidades y textura propuestas, sin prueba de cocina. El açaí debe ser pulpa congelada sin azúcar, apta para consumo directo según la etiqueta; sorbete, polvo, bebida o mezcla con guaraná y azúcar no son equivalentes. El plátano aporta dulzor; no se incorpora miel ni sirope. No se presenta el bowl como detox, adelgazante ni tratamiento. Lava la fruta bajo agua corriente antes de pelarla o cortarla; no uses jabón. Mantén la pulpa congelada hasta prepararla y respeta el manual de la batidora, apagándola y desenchufándola antes de tocar el interior. Sirve inmediatamente; como previsión doméstica no ensayada, guarda solo la base sobrante tapada a 4 °C o menos y consúmela en 24 horas, conservando la cobertura seca aparte. La textura pierde firmeza en frío; no se garantiza que recupere el resultado al volver a congelarla. No dejes alimentos perecederos más de 2 horas a temperatura ambiente, o 1 hora si supera 32 °C. Contiene almendras; granola y pulpa pueden contener otros frutos secos, gluten, soja o leche según la marca. Revisa etiquetas. Puedes sustituir las almendras por semillas si son apropiadas para tus comensales, o la granola por copos tostados listos para comer, pero cambia la nutrición. No sustituyas açaí por otra fruta y mantengas el mismo nombre de receta. La estimación usa una ficha USDA de pulpa comercial sin azúcar y granola genérica; la etiqueta real puede diferir.</p>"},{"id":"7bfd4b86-91b1-5c7b-9329-d79bd7423b1d","recipe_group_id":"b6b4397e-f51a-4c05-bf7a-fa285432829b","slug":"acai-bowl","public_path":"/de/acai-bowl","source_url":"https://manualdecocina.com/de/acai-bowl/","language":"de","title":"Açaí-Bowl mit Banane, Erdbeeren und Granola","excerpt":"Dicke Açaí-Bananen-Creme mit abgewogenen Früchten, Granola und Mandeln: zwei vorgeschlagene Bowls mit geschätzten Nährwerten.","summary":"Ungesüßtes gefrorenes Açaí und gefrorene Banane bilden eine löffelbare Basis mit Erdbeeren, Granola und Mandeln. Vorgeschlagen sind zwei Bowls und 135 Minuten einschließlich des vorherigen Einfrierens. Rezept, Konsistenz und Zeiten sind noch nicht in der Küche erprobt.","category":"Desserts","category_slug":"postres","difficulty":"Einfach","course":"Frühstück oder Dessert","cuisine":"Brasilianisch inspiriert","prep_time_minutes":15,"cook_time_minutes":0,"total_time_minutes":135,"servings":2,"ingredients":[{"name":"ungesüßtes gefrorenes Açaí-Püree, zum direkten Verzehr geeignet","amount":"200","unit":"g","group":"Basis"},{"name":"reife geschälte Banane zum Einfrieren","amount":"160","unit":"g","group":"Basis"},{"name":"kaltes Trinkwasser","amount":"60","unit":"g","group":"Basis"},{"name":"frische reife geschälte Banane","amount":"60","unit":"g","group":"Topping"},{"name":"frische Erdbeeren ohne Stielansatz","amount":"100","unit":"g","group":"Topping"},{"name":"verzehrfertige Granola","amount":"40","unit":"g","group":"Topping"},{"name":"naturbelassene Mandelblättchen","amount":"20","unit":"g","group":"Topping"}],"steps":[{"title":"Banane für die Basis einfrieren","content":"Hände waschen und die Banane vor dem Schälen abspülen. 160 g reifes Fruchtfleisch abwiegen, in 1 cm dicke Scheiben schneiden und einzeln auf einem sauberen Blech verteilen. Bei−18 °C oder kälter ungefähr 120 Minuten einfrieren, bis die Scheiben hart sind; nötigenfalls verlängern und die tatsächliche Zeit notieren. Die frische Banane für das Topping separat bereithalten. Diese 120 Minuten gehören zu den vorgeschlagenen 135 Minuten Gesamtzeit. Sind die 160 g bereits gefroren, werden 15 Minuten für die Zubereitung angesetzt.","image_url":"/recetas/acai-bowl/paso-01.webp","image_alt":"Açaí-Bowl mit Banane, Erdbeeren und Granola: Banane für die Basis einfrieren"},{"title":"Topping und Geräte vorbereiten","content":"Während die Banane fertig gefriert, Erdbeeren unter fließendem Wasser ohne Seife abspülen, trocknen, entstielen und 100 g abwiegen; in Scheiben schneiden. 60 g frische Banane schälen und schneiden,40 g verzehrfertige Granola und 20 g Mandelblättchen abwiegen. 60 g kaltes Trinkwasser abmessen. Zwei Schalen mit etwa 400 ml Fassungsvermögen und einen laut Anleitung für gefrorenes Obst geeigneten Mixer vorbereiten. Geschnittenes Obst bis zum Anrichten kalt halten.","image_url":"/recetas/acai-bowl/paso-02.webp","image_alt":"Açaí-Bowl mit Banane, Erdbeeren und Granola: Topping und Geräte vorbereiten"},{"title":"Gefrorenes Açaí zerkleinern","content":"Prüfen, dass das Püree ungesüßt und laut Verpackung direkt verzehrfertig ist; dieses Rezept ersetzt keine vorgeschriebene Erhitzung. 200 g erst unmittelbar vor dem Mixen herausnehmen. Geschlossene Beutel vorsichtig biegen, um das Püree zu brechen, oder die Außenseite etwa 20 Sekunden unter Wasser halten, damit es sich löst, ohne ganz aufzutauen. Verpackung trocknen, an der vorgesehenen Stelle öffnen und die Stücke in eine saubere Schale geben. Messer oder Schere vorsichtig und von der Hand weg führen; Plastikreste vermeiden.","image_url":"/recetas/acai-bowl/paso-03.webp","image_alt":"Açaí-Bowl mit Banane, Erdbeeren und Granola: Gefrorenes Açaí zerkleinern"},{"title":"Zu einer dicken Creme mixen","content":"Zuerst 60 g Wasser, dann 160 g gefrorene Banane und 200 g Açaí-Stücke in den Mixbehälter geben; Anleitung und Fassungsvermögen beachten. Deckel schließen und in kurzen Intervallen insgesamt ungefähr 1 Minute mixen, bis eine dicke violette Creme ohne große Stücke entsteht. Zum Abschaben ausschalten und den Netzstecker ziehen; niemals Hände oder Werkzeuge bei laufenden Klingen hineinhalten. Den Motor nicht überlasten: nötigenfalls kurz antauen lassen. Zusätzliches Wasser verändert Konsistenz und Referenzgewicht.","image_url":"/recetas/acai-bowl/paso-04.webp","image_alt":"Açaí-Bowl mit Banane, Erdbeeren und Granola: Zu einer dicken Creme mixen"},{"title":"Creme auf zwei Schalen verteilen","content":"Bei stillstehenden Klingen die gesamte Basis auf beide Schalen verteilen: je etwa 210 g vor dem Topping, abhängig davon, wie viel aus dem Mixer entnommen wird. Mit einem Löffel glätten. Die Creme soll Früchte tragen und sich löffeln lassen. Ist sie zu flüssig, einige Minuten im Gefrierfach kühlen und diese zusätzliche Zeit notieren; überschüssiges Wasser nicht durch Eiswürfel kaschieren.","image_url":"/recetas/acai-bowl/paso-05.webp","image_alt":"Açaí-Bowl mit Banane, Erdbeeren und Granola: Creme auf zwei Schalen verteilen"},{"title":"Topping auflegen und sofort servieren","content":"Jede Schale mit 30 g frischer Banane,50 g Erdbeeren,20 g Granola und 10 g Mandelblättchen belegen. In Streifen anordnen und violette Creme sichtbar lassen. Sofort servieren. Vorgeschlagen sind 2 Bowls von ungefähr 320 g mit 15 Minuten Arbeitszeit und 120 Minuten vorherigem Einfrieren, ohne Kochen. Mengen, Konsistenz, Zeiten und Ausbeute sind Schätzungen und noch nicht erprobt. Die Nährwerte enthalten das gesamte angegebene Topping.","image_url":"/recetas/acai-bowl/portada.webp","image_alt":"Açaí-Bowl mit Banane, Erdbeeren und Granola: Topping auflegen und sofort servieren"}],"nutrition":{"calories":339.6,"protein_g":7.4,"carbs_g":45.9,"fat_g":15.4,"saturated_fat_g":2.3,"fiber_g":9.9,"sugar_g":20.3,"sodium_mg":18,"estimated":true,"source":"USDA FoodData Central — SR Legacy / Branded","source_url":"https://fdc.nal.usda.gov/download-datasets/","inputs":[{"ingredient":"ungesüßtes gefrorenes Açaí-Püree, zum direkten Verzehr geeignet","edible_grams":200,"fdc_id":2653289,"fdc_description":"ZERO SUGAR PURE UNSWEETENED AA BERRY SUPERFRUIT PACKS, AA BERRY","per_100g":{"calories":70,"protein_g":1,"carbs_g":4,"fat_g":5,"saturated_fat_g":1,"fiber_g":3,"sugar_g":0,"sodium_mg":10},"source_url":"https://fdc.nal.usda.gov/food-details/2653289/nutrients"},{"ingredient":"reife geschälte Banane zum Einfrieren","edible_grams":160,"fdc_id":173944,"fdc_description":"Bananas, raw","per_100g":{"calories":89,"protein_g":1.09,"carbs_g":22.8,"fat_g":0.33,"saturated_fat_g":0.112,"fiber_g":2.6,"sugar_g":12.2,"sodium_mg":1},"source_url":"https://fdc.nal.usda.gov/food-details/173944/nutrients"},{"ingredient":"kaltes Trinkwasser","edible_grams":60,"fdc_id":173647,"fdc_description":"Beverages, water, tap, drinking","per_100g":{"calories":0,"protein_g":0,"carbs_g":0,"fat_g":0,"saturated_fat_g":0,"fiber_g":0,"sugar_g":0,"sodium_mg":4},"source_url":"https://fdc.nal.usda.gov/food-details/173647/nutrients"},{"ingredient":"frische reife geschälte Banane","edible_grams":60,"fdc_id":173944,"fdc_description":"Bananas, raw","per_100g":{"calories":89,"protein_g":1.09,"carbs_g":22.8,"fat_g":0.33,"saturated_fat_g":0.112,"fiber_g":2.6,"sugar_g":12.2,"sodium_mg":1},"source_url":"https://fdc.nal.usda.gov/food-details/173944/nutrients"},{"ingredient":"frische Erdbeeren ohne Stielansatz","edible_grams":100,"fdc_id":167762,"fdc_description":"Strawberries, raw","per_100g":{"calories":32,"protein_g":0.67,"carbs_g":7.68,"fat_g":0.3,"saturated_fat_g":0.015,"fiber_g":2,"sugar_g":4.89,"sodium_mg":1},"source_url":"https://fdc.nal.usda.gov/food-details/167762/nutrients"},{"ingredient":"verzehrfertige Granola","edible_grams":40,"fdc_id":171646,"fdc_description":"Cereals ready-to-eat, granola, homemade","per_100g":{"calories":489,"protein_g":13.7,"carbs_g":53.9,"fat_g":24.3,"saturated_fat_g":3.96,"fiber_g":8.9,"sugar_g":19.8,"sodium_mg":26},"source_url":"https://fdc.nal.usda.gov/food-details/171646/nutrients"},{"ingredient":"naturbelassene Mandelblättchen","edible_grams":20,"fdc_id":170567,"fdc_description":"Nuts, almonds","per_100g":{"calories":579,"protein_g":21.2,"carbs_g":21.6,"fat_g":49.9,"saturated_fat_g":3.8,"fiber_g":12.5,"sugar_g":4.35,"sodium_mg":1},"source_url":"https://fdc.nal.usda.gov/food-details/170567/nutrients"}],"serving_size":"Eine Bowl; vorgeschlagen sind 2 Portionen von etwa 320 g, Endgewicht nicht gemessen","method":"Sieben essbare Zutatenmengen in Gramm mit den acht USDA-Werten je 100 g multiplizieren, summieren und durch 2 teilen. Banane für Basis und Topping wird separat mit demselben Datensatz gerechnet. Alle 60 g Wasser, Granola und Mandeln sind enthalten; keine erfundenen Verluste durch Einfrieren oder Mixen.","note":"Zutatenbasierte Schätzung, keine Laboranalyse oder Küchenerprobung. Ungesüßtes Püree: FDC 2653289,Sambazon, veröffentlicht 2023-10-26; kein allgemeiner Wert für alle Marken, Pulver, Getränke oder Sorbet. Allgemeine hausgemachte Granola FDC 171646 dient als Referenz; Zucker, Natrium und Fett können abweichen. Trinkwasser FDC 173647 hat variable Mineralgehalte. Alle acht Werte sind vorhanden; fehlende Angaben werden niemals mit null aufgefüllt."},"image_url":"/recetas/acai-bowl/portada.webp","gallery":[{"url":"/recetas/acai-bowl/portada.webp","alt":"Zwei Schalen mit dicker violetter Açaí-Creme und Streifen aus Banane, Erdbeeren, Granola und Mandelblättchen"}],"published":true,"editorial_status":"published","keywords":["Açaí-Bowl","Açaí mit Banane","Açaí mit Granola"],"notes":"Vorgeschlagene Mengen und Konsistenz, ohne Küchentest. Nur ungesüßtes gefrorenes Açaí-Püree verwenden, das laut Etikett direkt verzehrfertig ist; Sorbet, Pulver, Getränke oder Mischungen mit Guaraná und Zucker sind nicht gleichwertig. Die Banane süßt die Creme; Honig und Sirup werden nicht zugesetzt. Die Bowl wird nicht als Detox, Schlankheitsmittel oder Behandlung dargestellt. Obst vor dem Schälen oder Schneiden unter fließendem Wasser ohne Seife waschen. Püree bis zur Verarbeitung gefroren halten. Mixeranleitung beachten und vor Berühren des Innenraums ausschalten und ausstecken. Sofort servieren. Als nicht geprüfter Haushaltsvorschlag kann nur die übrige Basis abgedeckt bei 4 °C oder kälter aufbewahrt und innerhalb von 24 Stunden verzehrt werden; trockene Toppings separat lagern. Gekühlt wird die Creme weicher; erneutes Einfrieren garantiert nicht dieselbe Konsistenz. Verderbliche Lebensmittel höchstens 2 Stunden bei Raumtemperatur stehen lassen, bei mehr als 32 °C höchstens 1 Stunde. Enthält Mandeln; Granola und Püree können je nach Marke weitere Nüsse, Gluten, Soja oder Milch enthalten. Etiketten prüfen. Geeignete Samen statt Mandeln oder verzehrfertige geröstete Haferflocken statt Granola verändern die Nährwerte. Açaí nicht durch anderes Obst ersetzen und denselben Rezeptnamen beibehalten. Die Schätzung nutzt USDA-Daten für kommerzielles ungesüßtes Püree und allgemeine Granola; das tatsächliche Etikett kann abweichen.","seo":{"title":"Açaí-Bowl mit Banane und Granola Schritt für Schritt","description":"Zwei dicke Açaí-Bowls mit gefrorener Banane, Erdbeeren, Granola und Mandeln zubereiten. Vorgeschlagene Mengen, vollständige Zeiten und geschätzte Nährwerte.","image_alt":"Zwei Schalen mit dicker violetter Açaí-Creme und Streifen aus Banane, Erdbeeren, Granola und Mandelblättchen","image_variants":["/recetas/acai-bowl/portada-1x1.webp","/recetas/acai-bowl/portada-4x3.webp","/recetas/acai-bowl/portada-16x9.webp"],"faq":[{"q":"Welches Açaí eignet sich?","a":"200 g ungesüßtes gefrorenes Püree verwenden, das laut Etikett direkt verzehrfertig ist. Sorbet, Pulver und gesüßte Mischungen besitzen eine andere Zusammensetzung und Konsistenz. Die Nährwertschätzung verwendet einen kommerziellen USDA-Referenzdatensatz."},{"q":"Warum ist die Creme flüssig oder blockiert der Mixer?","a":"Banane gefroren und Açaí nur wenig angetaut verwenden. Die Basis enthält vorgeschlagene 60 g Wasser; mehr Wasser verdünnt sie. Einen für Gefrorenes geeigneten Mixer benutzen und den Motor nicht überlasten. Vor dem Abschaben ausschalten und ausstecken; bei Bedarf kurz antauen lassen."},{"q":"Wie lange dauert es und kann ich Reste aufbewahren?","a":"Geschätzt 135 Minuten:120 Minuten zum Einfrieren von 160 g Banane und 15 Minuten Arbeit. Mit bereits gefrorener Banane werden 15 Minuten angesetzt. Beide Bowls sofort servieren. Übrige Basis abgedeckt bei 4 °C oder kälter innerhalb von 24 Stunden verbrauchen, als nicht geprüfter Haushaltsvorschlag; Toppings separat halten."}]},"content_html":"<p>Ungesüßtes gefrorenes Açaí und gefrorene Banane bilden eine löffelbare Basis mit Erdbeeren, Granola und Mandeln. Vorgeschlagen sind zwei Bowls und 135 Minuten einschließlich des vorherigen Einfrierens. Rezept, Konsistenz und Zeiten sind noch nicht in der Küche erprobt.</p><p>Vorgeschlagene Mengen und Konsistenz, ohne Küchentest. Nur ungesüßtes gefrorenes Açaí-Püree verwenden, das laut Etikett direkt verzehrfertig ist; Sorbet, Pulver, Getränke oder Mischungen mit Guaraná und Zucker sind nicht gleichwertig. Die Banane süßt die Creme; Honig und Sirup werden nicht zugesetzt. Die Bowl wird nicht als Detox, Schlankheitsmittel oder Behandlung dargestellt. Obst vor dem Schälen oder Schneiden unter fließendem Wasser ohne Seife waschen. Püree bis zur Verarbeitung gefroren halten. Mixeranleitung beachten und vor Berühren des Innenraums ausschalten und ausstecken. Sofort servieren. Als nicht geprüfter Haushaltsvorschlag kann nur die übrige Basis abgedeckt bei 4 °C oder kälter aufbewahrt und innerhalb von 24 Stunden verzehrt werden; trockene Toppings separat lagern. Gekühlt wird die Creme weicher; erneutes Einfrieren garantiert nicht dieselbe Konsistenz. Verderbliche Lebensmittel höchstens 2 Stunden bei Raumtemperatur stehen lassen, bei mehr als 32 °C höchstens 1 Stunde. Enthält Mandeln; Granola und Püree können je nach Marke weitere Nüsse, Gluten, Soja oder Milch enthalten. Etiketten prüfen. Geeignete Samen statt Mandeln oder verzehrfertige geröstete Haferflocken statt Granola verändern die Nährwerte. Açaí nicht durch anderes Obst ersetzen und denselben Rezeptnamen beibehalten. Die Schätzung nutzt USDA-Daten für kommerzielles ungesüßtes Püree und allgemeine Granola; das tatsächliche Etikett kann abweichen.</p>"},{"id":"1f8ba9ed-813e-5479-993f-7c62759b8a17","recipe_group_id":"b6b4397e-f51a-4c05-bf7a-fa285432829b","slug":"bol-dacai","public_path":"/en/bol-dacai","source_url":"https://manualdecocina.com/en/bol-dacai/","language":"en","title":"Açaí bowl with banana, strawberries and granola","excerpt":"Thick açaí and frozen banana topped with measured fruit, granola and almonds: two proposed bowls with estimated nutrition per serving.","summary":"Unsweetened frozen açaí and frozen banana make a spoonable base topped with strawberries, granola and almonds. The proposal yields two bowls in 135 minutes including freezing the banana beforehand. Formula, texture and timings await a kitchen test.","category":"Desserts","category_slug":"postres","difficulty":"Easy","course":"Breakfast or dessert","cuisine":"Brazilian inspired","prep_time_minutes":15,"cook_time_minutes":0,"total_time_minutes":135,"servings":2,"ingredients":[{"name":"unsweetened frozen açaí purée, labelled ready to eat","amount":"200","unit":"g","group":"Base"},{"name":"ripe peeled banana for freezing","amount":"160","unit":"g","group":"Base"},{"name":"cold drinking water","amount":"60","unit":"g","group":"Base"},{"name":"fresh ripe peeled banana","amount":"60","unit":"g","group":"Toppings"},{"name":"fresh strawberries, hulled","amount":"100","unit":"g","group":"Toppings"},{"name":"ready-to-eat granola","amount":"40","unit":"g","group":"Toppings"},{"name":"raw sliced almonds","amount":"20","unit":"g","group":"Toppings"}],"steps":[{"title":"Freeze the banana for the base","content":"Wash your hands and rinse the banana before peeling it. Weigh 160 g of ripe flesh and cut into 1 cm slices. Spread separately on a clean tray and freeze at−18 °C or colder for approximately 120 minutes until hard; extend as needed and record the actual time. Keep the fresh topping banana separate. These 120 minutes are included in the proposed 135-minute total. If the 160 g is already frozen, assembly is estimated at 15 minutes.","image_url":"/recetas/acai-bowl/paso-01.webp","image_alt":"Açaí bowl with banana, strawberries and granola: Freeze the banana for the base"},{"title":"Prepare the toppings and equipment","content":"While the banana finishes freezing, rinse the strawberries under running water without soap, dry, hull and weigh 100 g; slice them. Peel and slice 60 g of fresh banana; weigh 40 g of ready-to-eat granola and 20 g of sliced almonds. Measure 60 g of cold drinking water. Prepare two bowls holding about 400 ml and a blender rated for frozen fruit according to its manual. Keep cut fruit chilled until assembly.","image_url":"/recetas/acai-bowl/paso-02.webp","image_alt":"Açaí bowl with banana, strawberries and granola: Prepare the toppings and equipment"},{"title":"Break up the frozen açaí","content":"Check that the purée is unsweetened and labelled ready to eat; this recipe does not replace any cooking required by the package. Remove 200 g from the freezer just before blending. Flex the sealed packs to break the purée, or run water over the outside for about 20 seconds to loosen it without thawing completely. Dry the pack, open at the indicated point and tip the pieces into a clean bowl. Handle a knife or scissors carefully, cutting away from your hand and preventing plastic fragments from entering the food.","image_url":"/recetas/acai-bowl/paso-03.webp","image_alt":"Açaí bowl with banana, strawberries and granola: Break up the frozen açaí"},{"title":"Blend a thick base","content":"Put the 60 g water in the jug first, followed by 160 g frozen banana and 200 g broken açaí, observing the blender instructions and capacity. Secure the lid and pulse in short bursts, blending for about 1 minute in total to make a thick purple cream without large chunks. Switch off and unplug before scraping down with a spatula; never put utensils or hands near moving blades. Do not strain the motor; allow the fruit to soften briefly if it cannot turn. Extra water changes the texture and reference weight.","image_url":"/recetas/acai-bowl/paso-04.webp","image_alt":"Açaí bowl with banana, strawberries and granola: Blend a thick base"},{"title":"Divide between two bowls","content":"With the blades stopped, divide all the base between the two bowls, about 210 g each before toppings, depending on how much is recovered from the jug. Level gently with a spoon. It should hold fruit on top and be eaten with a spoon. If too runny, chill briefly in the freezer and record the additional time. Do not add ice to disguise excess water.","image_url":"/recetas/acai-bowl/paso-05.webp","image_alt":"Açaí bowl with banana, strawberries and granola: Divide between two bowls"},{"title":"Top and serve immediately","content":"Add 30 g fresh banana,50 g strawberries,20 g granola and 10 g sliced almonds to each bowl. Arrange in bands, leaving some purple base visible. Serve immediately. The proposal yields 2 bowls of about 320 g, with 15 minutes of work and 120 minutes of advance freezing, without cooking. Quantities, texture, timings and yield are estimates awaiting a kitchen test. The calories include every listed topping.","image_url":"/recetas/acai-bowl/portada.webp","image_alt":"Açaí bowl with banana, strawberries and granola: Top and serve immediately"}],"nutrition":{"calories":339.6,"protein_g":7.4,"carbs_g":45.9,"fat_g":15.4,"saturated_fat_g":2.3,"fiber_g":9.9,"sugar_g":20.3,"sodium_mg":18,"estimated":true,"source":"USDA FoodData Central — SR Legacy / Branded","source_url":"https://fdc.nal.usda.gov/download-datasets/","inputs":[{"ingredient":"unsweetened frozen açaí purée, labelled ready to eat","edible_grams":200,"fdc_id":2653289,"fdc_description":"ZERO SUGAR PURE UNSWEETENED AA BERRY SUPERFRUIT PACKS, AA BERRY","per_100g":{"calories":70,"protein_g":1,"carbs_g":4,"fat_g":5,"saturated_fat_g":1,"fiber_g":3,"sugar_g":0,"sodium_mg":10},"source_url":"https://fdc.nal.usda.gov/food-details/2653289/nutrients"},{"ingredient":"ripe peeled banana for freezing","edible_grams":160,"fdc_id":173944,"fdc_description":"Bananas, raw","per_100g":{"calories":89,"protein_g":1.09,"carbs_g":22.8,"fat_g":0.33,"saturated_fat_g":0.112,"fiber_g":2.6,"sugar_g":12.2,"sodium_mg":1},"source_url":"https://fdc.nal.usda.gov/food-details/173944/nutrients"},{"ingredient":"cold drinking water","edible_grams":60,"fdc_id":173647,"fdc_description":"Beverages, water, tap, drinking","per_100g":{"calories":0,"protein_g":0,"carbs_g":0,"fat_g":0,"saturated_fat_g":0,"fiber_g":0,"sugar_g":0,"sodium_mg":4},"source_url":"https://fdc.nal.usda.gov/food-details/173647/nutrients"},{"ingredient":"fresh ripe peeled banana","edible_grams":60,"fdc_id":173944,"fdc_description":"Bananas, raw","per_100g":{"calories":89,"protein_g":1.09,"carbs_g":22.8,"fat_g":0.33,"saturated_fat_g":0.112,"fiber_g":2.6,"sugar_g":12.2,"sodium_mg":1},"source_url":"https://fdc.nal.usda.gov/food-details/173944/nutrients"},{"ingredient":"fresh strawberries, hulled","edible_grams":100,"fdc_id":167762,"fdc_description":"Strawberries, raw","per_100g":{"calories":32,"protein_g":0.67,"carbs_g":7.68,"fat_g":0.3,"saturated_fat_g":0.015,"fiber_g":2,"sugar_g":4.89,"sodium_mg":1},"source_url":"https://fdc.nal.usda.gov/food-details/167762/nutrients"},{"ingredient":"ready-to-eat granola","edible_grams":40,"fdc_id":171646,"fdc_description":"Cereals ready-to-eat, granola, homemade","per_100g":{"calories":489,"protein_g":13.7,"carbs_g":53.9,"fat_g":24.3,"saturated_fat_g":3.96,"fiber_g":8.9,"sugar_g":19.8,"sodium_mg":26},"source_url":"https://fdc.nal.usda.gov/food-details/171646/nutrients"},{"ingredient":"raw sliced almonds","edible_grams":20,"fdc_id":170567,"fdc_description":"Nuts, almonds","per_100g":{"calories":579,"protein_g":21.2,"carbs_g":21.6,"fat_g":49.9,"saturated_fat_g":3.8,"fiber_g":12.5,"sugar_g":4.35,"sodium_mg":1},"source_url":"https://fdc.nal.usda.gov/food-details/170567/nutrients"}],"serving_size":"One bowl;2 proposed servings of about 320 g, finished weight not measured","method":"Multiply seven edible ingredient weights by their eight USDA values per 100 g, sum and divide by 2. Base and topping banana are calculated separately using the same food record. Includes all 60 g water, granola and almonds, without invented losses from freezing or blending.","note":"Ingredient-based estimate, not laboratory analysis or kitchen testing. Commercial unsweetened purée is represented by FDC 2653289,Sambazon,published 2023-10-26; it does not represent all brands, powders, drinks or sorbets. Generic homemade granola FDC 171646 is a reference, with sugar, sodium and fat varying by label. Drinking water uses FDC 173647 and its minerals vary. All eight nutrients are present in the records; missing values are never filled with zero."},"image_url":"/recetas/acai-bowl/portada.webp","gallery":[{"url":"/recetas/acai-bowl/portada.webp","alt":"Two bowls of thick purple açaí topped with bands of banana, strawberries, granola and sliced almonds"}],"published":true,"editorial_status":"published","keywords":["açaí bowl","banana açaí bowl","açaí with granola"],"notes":"Proposed quantities and texture, without a kitchen test. Use unsweetened frozen açaí purée labelled ready to eat; sorbet, powder, drinks and sugary guaraná blends are not equivalent. Banana supplies sweetness; no honey or syrup is added. The bowl is not presented as a detox, slimming product or treatment. Rinse fruit under running water before peeling or cutting; do not use soap. Keep the purée frozen until preparation. Follow the blender manual, switching off and unplugging before touching its interior. Serve immediately. As an untested household proposal, refrigerate only leftover base covered at 4 °C or below and eat within 24 hours, keeping dry toppings separate. The texture softens in storage; refreezing is not guaranteed to restore it. Do not leave perishable food at room temperature for more than 2 hours, or 1 hour above 32 °C. Contains almonds; granola and purée may contain other nuts, gluten, soy or milk depending on the brand. Check labels. Suitable seeds may replace almonds, or ready-to-eat toasted oats may replace granola, but nutrition changes. Do not replace açaí with another fruit while keeping the same recipe name. Nutrition uses a USDA commercial unsweetened purée reference and generic granola; the actual label may differ.","seo":{"title":"Açaí bowl with banana and granola, step by step","description":"Make two thick açaí bowls with frozen banana, strawberries, granola and almonds. Proposed weights, freezing time included and estimated nutrition.","image_alt":"Two bowls of thick purple açaí topped with bands of banana, strawberries, granola and sliced almonds","image_variants":["/recetas/acai-bowl/portada-1x1.webp","/recetas/acai-bowl/portada-4x3.webp","/recetas/acai-bowl/portada-16x9.webp"],"faq":[{"q":"Which açaí should I use?","a":"Use 200 g unsweetened frozen purée labelled ready to eat. Sorbet, powder and sweetened blends differ in composition and texture. The nutrition estimate uses a commercial USDA reference food."},{"q":"Why is it runny, or why does the blender struggle?","a":"The banana should be frozen and the açaí only slightly softened. The proposed base contains 60 g water; adding more thins it. Use a blender suitable for frozen fruit without straining its motor. Switch off and unplug before scraping down; soften briefly if your equipment requires it."},{"q":"How long does it take, and can I store it?","a":"Allow an estimated 135 minutes:120 to freeze 160 g banana and 15 for preparation. With banana already frozen, assembly is estimated at 15 minutes. Serve both bowls immediately. Refrigerate covered leftover base at 4 °C or below and use within 24 hours as an untested household proposal, storing toppings separately."}]},"content_html":"<p>Unsweetened frozen açaí and frozen banana make a spoonable base topped with strawberries, granola and almonds. The proposal yields two bowls in 135 minutes including freezing the banana beforehand. Formula, texture and timings await a kitchen test.</p><p>Proposed quantities and texture, without a kitchen test. Use unsweetened frozen açaí purée labelled ready to eat; sorbet, powder, drinks and sugary guaraná blends are not equivalent. Banana supplies sweetness; no honey or syrup is added. The bowl is not presented as a detox, slimming product or treatment. Rinse fruit under running water before peeling or cutting; do not use soap. Keep the purée frozen until preparation. Follow the blender manual, switching off and unplugging before touching its interior. Serve immediately. As an untested household proposal, refrigerate only leftover base covered at 4 °C or below and eat within 24 hours, keeping dry toppings separate. The texture softens in storage; refreezing is not guaranteed to restore it. Do not leave perishable food at room temperature for more than 2 hours, or 1 hour above 32 °C. Contains almonds; granola and purée may contain other nuts, gluten, soy or milk depending on the brand. Check labels. Suitable seeds may replace almonds, or ready-to-eat toasted oats may replace granola, but nutrition changes. Do not replace açaí with another fruit while keeping the same recipe name. Nutrition uses a USDA commercial unsweetened purée reference and generic granola; the actual label may differ.</p>"},{"id":"af7a9114-3a4c-504f-a290-cc2477fe1eb0","recipe_group_id":"b6b4397e-f51a-4c05-bf7a-fa285432829b","slug":"bol-dacai","public_path":"/fr/bol-dacai","source_url":"https://manualdecocina.com/fr/bol-dacai/","language":"fr","title":"Bol d’açaí à la banane, aux fraises et au granola","excerpt":"Une crème épaisse d’açaí et de banane congelée, garnie de fruits, granola et amandes pesés : deux bols proposés et une nutrition estimée.","summary":"L’açaí congelé sans sucre et la banane congelée forment une base à manger à la cuillère, garnie de fraises, de granola et d’amandes. Deux bols et 135 minutes sont proposés, congélation préalable comprise. Formule, texture et durées restent à tester en cuisine.","category":"Desserts","category_slug":"postres","difficulty":"Facile","course":"Petit-déjeuner ou dessert","cuisine":"Inspiration brésilienne","prep_time_minutes":15,"cook_time_minutes":0,"total_time_minutes":135,"servings":2,"ingredients":[{"name":"purée d’açaí congelée sans sucre, prête à consommer selon l’étiquette","amount":"200","unit":"g","group":"Base"},{"name":"banane mûre épluchée à congeler","amount":"160","unit":"g","group":"Base"},{"name":"eau potable froide","amount":"60","unit":"g","group":"Base"},{"name":"banane mûre fraîche épluchée","amount":"60","unit":"g","group":"Garniture"},{"name":"fraises fraîches équeutées","amount":"100","unit":"g","group":"Garniture"},{"name":"granola prêt à consommer","amount":"40","unit":"g","group":"Garniture"},{"name":"amandes effilées nature","amount":"20","unit":"g","group":"Garniture"}],"steps":[{"title":"Congelez la banane de la base","content":"Lavez-vous les mains et rincez la banane avant de l’éplucher. Pesez 160 g de chair mûre et coupez-la en rondelles de 1 cm. Disposez-les séparément sur une plaque propre et congelez à−18 °C ou moins pendant environ 120 minutes, jusqu’à ce qu’elles soient dures ; prolongez si nécessaire et notez la durée réelle. Gardez à part la banane fraîche de la garniture. Ces 120 minutes font partie des 135 minutes totales proposées. Si les 160 g sont déjà congelés, le montage est estimé à 15 minutes.","image_url":"/recetas/acai-bowl/paso-01.webp","image_alt":"Bol d’açaí à la banane, aux fraises et au granola: Congelez la banane de la base"},{"title":"Préparez la garniture et le matériel","content":"Pendant la fin de la congélation, rincez les fraises sous l’eau courante sans savon, séchez-les, équeutez-les et pesez 100 g ; coupez-les en lamelles. Épluchez et coupez 60 g de banane fraîche, puis pesez 40 g de granola prêt à manger et 20 g d’amandes effilées. Mesurez 60 g d’eau potable froide. Préparez deux bols d’environ 400 ml et un blender adapté aux fruits congelés selon son manuel. Gardez les fruits coupés au froid jusqu’au montage.","image_url":"/recetas/acai-bowl/paso-02.webp","image_alt":"Bol d’açaí à la banane, aux fraises et au granola: Préparez la garniture et le matériel"},{"title":"Cassez la purée d’açaí congelée","content":"Vérifiez que la purée est sans sucre et prête à consommer d’après l’emballage ; cette recette ne remplace pas une cuisson exigée par l’étiquette. Sortez 200 g du congélateur juste avant de mixer. Pliez doucement les sachets fermés pour casser la purée, ou passez leur extérieur sous l’eau pendant environ 20 secondes pour la détacher sans la décongeler entièrement. Séchez l’emballage, ouvrez-le à l’endroit prévu et versez les morceaux dans un bol propre. Utilisez couteau ou ciseaux avec précaution, loin de la main, et évitez tout fragment de plastique.","image_url":"/recetas/acai-bowl/paso-03.webp","image_alt":"Bol d’açaí à la banane, aux fraises et au granola: Cassez la purée d’açaí congelée"},{"title":"Mixez une base épaisse","content":"Versez d’abord les 60 g d’eau dans le récipient, puis les 160 g de banane congelée et les 200 g d’açaí en morceaux, en respectant le manuel et la capacité du blender. Fermez le couvercle et mixez par courtes impulsions, environ 1 minute au total, pour obtenir une crème violette épaisse sans gros morceaux. Éteignez et débranchez avant de rabattre la préparation à la spatule ; ne mettez jamais mains ou ustensiles près des lames en mouvement. Ne forcez pas le moteur : laissez ramollir brièvement si nécessaire. Plus d’eau modifie la texture et le poids de référence.","image_url":"/recetas/acai-bowl/paso-04.webp","image_alt":"Bol d’açaí à la banane, aux fraises et au granola: Mixez une base épaisse"},{"title":"Répartissez la crème dans deux bols","content":"Une fois les lames arrêtées, répartissez toute la base entre les deux bols, environ 210 g par bol avant garniture selon la quantité récupérée. Lissez doucement à la cuillère. La crème doit porter les fruits en surface et se manger à la cuillère. Si elle est trop liquide, placez-la brièvement au congélateur et notez ce temps supplémentaire. N’ajoutez pas de glaçons pour masquer un excès d’eau.","image_url":"/recetas/acai-bowl/paso-05.webp","image_alt":"Bol d’açaí à la banane, aux fraises et au granola: Répartissez la crème dans deux bols"},{"title":"Garnissez et servez aussitôt","content":"Ajoutez dans chaque bol 30 g de banane fraîche,50 g de fraises,20 g de granola et 10 g d’amandes effilées. Formez des bandes en laissant de la crème violette visible. Servez immédiatement. On propose 2 bols d’environ 320 g, avec 15 minutes de travail et 120 minutes de congélation préalable, sans cuisson. Quantités, texture, durées et rendement sont estimés et restent à tester en cuisine. Les calories comprennent toute la garniture indiquée.","image_url":"/recetas/acai-bowl/portada.webp","image_alt":"Bol d’açaí à la banane, aux fraises et au granola: Garnissez et servez aussitôt"}],"nutrition":{"calories":339.6,"protein_g":7.4,"carbs_g":45.9,"fat_g":15.4,"saturated_fat_g":2.3,"fiber_g":9.9,"sugar_g":20.3,"sodium_mg":18,"estimated":true,"source":"USDA FoodData Central — SR Legacy / Branded","source_url":"https://fdc.nal.usda.gov/download-datasets/","inputs":[{"ingredient":"purée d’açaí congelée sans sucre, prête à consommer selon l’étiquette","edible_grams":200,"fdc_id":2653289,"fdc_description":"ZERO SUGAR PURE UNSWEETENED AA BERRY SUPERFRUIT PACKS, AA BERRY","per_100g":{"calories":70,"protein_g":1,"carbs_g":4,"fat_g":5,"saturated_fat_g":1,"fiber_g":3,"sugar_g":0,"sodium_mg":10},"source_url":"https://fdc.nal.usda.gov/food-details/2653289/nutrients"},{"ingredient":"banane mûre épluchée à congeler","edible_grams":160,"fdc_id":173944,"fdc_description":"Bananas, raw","per_100g":{"calories":89,"protein_g":1.09,"carbs_g":22.8,"fat_g":0.33,"saturated_fat_g":0.112,"fiber_g":2.6,"sugar_g":12.2,"sodium_mg":1},"source_url":"https://fdc.nal.usda.gov/food-details/173944/nutrients"},{"ingredient":"eau potable froide","edible_grams":60,"fdc_id":173647,"fdc_description":"Beverages, water, tap, drinking","per_100g":{"calories":0,"protein_g":0,"carbs_g":0,"fat_g":0,"saturated_fat_g":0,"fiber_g":0,"sugar_g":0,"sodium_mg":4},"source_url":"https://fdc.nal.usda.gov/food-details/173647/nutrients"},{"ingredient":"banane mûre fraîche épluchée","edible_grams":60,"fdc_id":173944,"fdc_description":"Bananas, raw","per_100g":{"calories":89,"protein_g":1.09,"carbs_g":22.8,"fat_g":0.33,"saturated_fat_g":0.112,"fiber_g":2.6,"sugar_g":12.2,"sodium_mg":1},"source_url":"https://fdc.nal.usda.gov/food-details/173944/nutrients"},{"ingredient":"fraises fraîches équeutées","edible_grams":100,"fdc_id":167762,"fdc_description":"Strawberries, raw","per_100g":{"calories":32,"protein_g":0.67,"carbs_g":7.68,"fat_g":0.3,"saturated_fat_g":0.015,"fiber_g":2,"sugar_g":4.89,"sodium_mg":1},"source_url":"https://fdc.nal.usda.gov/food-details/167762/nutrients"},{"ingredient":"granola prêt à consommer","edible_grams":40,"fdc_id":171646,"fdc_description":"Cereals ready-to-eat, granola, homemade","per_100g":{"calories":489,"protein_g":13.7,"carbs_g":53.9,"fat_g":24.3,"saturated_fat_g":3.96,"fiber_g":8.9,"sugar_g":19.8,"sodium_mg":26},"source_url":"https://fdc.nal.usda.gov/food-details/171646/nutrients"},{"ingredient":"amandes effilées nature","edible_grams":20,"fdc_id":170567,"fdc_description":"Nuts, almonds","per_100g":{"calories":579,"protein_g":21.2,"carbs_g":21.6,"fat_g":49.9,"saturated_fat_g":3.8,"fiber_g":12.5,"sugar_g":4.35,"sodium_mg":1},"source_url":"https://fdc.nal.usda.gov/food-details/170567/nutrients"}],"serving_size":"Un bol ;2 portions proposées d’environ 320 g, poids final non mesuré","method":"Multipliez sept poids comestibles par les huit valeurs USDA pour 100 g, additionnez et divisez par 2. Banane de base et de garniture calculées séparément avec la même fiche. Toute l’eau, soit 60 g, le granola et les amandes sont inclus, sans pertes inventées lors de la congélation ou du mixage.","note":"Estimation par ingrédients, sans analyse en laboratoire ni essai en cuisine. Purée commerciale sans sucre modélisée avec FDC 2653289,Sambazon, publiée 2023-10-26 ; elle ne représente pas toutes les marques, poudres, boissons ou sorbets. Granola maison générique FDC 171646 comme référence : sucres, sodium et lipides varient selon l’étiquette. Eau potable FDC 173647, minéraux variables. Les huit valeurs sont présentes ; aucune donnée manquante n’est remplacée par zéro."},"image_url":"/recetas/acai-bowl/portada.webp","gallery":[{"url":"/recetas/acai-bowl/portada.webp","alt":"Deux bols de crème d’açaí violette épaisse garnis en bandes de banane, fraises, granola et amandes effilées"}],"published":true,"editorial_status":"published","keywords":["bol d’açaí","açaí à la banane","açaí au granola"],"notes":"Quantités et texture proposées, sans essai en cuisine. Choisissez une purée d’açaí congelée sans sucre, prête à consommer selon l’étiquette ; sorbet, poudre, boisson ou mélange sucré au guaraná ne sont pas équivalents. La banane apporte la douceur ; ni miel ni sirop ne sont ajoutés. Le bol n’est pas présenté comme une détox, un produit amaigrissant ou un traitement. Rincez les fruits sous l’eau courante avant de les éplucher ou couper, sans savon. Gardez la purée congelée jusqu’à la préparation. Suivez le manuel du blender et éteignez puis débranchez avant de toucher l’intérieur. Servez aussitôt. À titre de proposition domestique non testée, conservez seulement la base restante couverte à 4 °C ou moins et consommez-la sous 24 heures ; gardez les garnitures sèches à part. La texture se ramollit au froid ; une nouvelle congélation ne garantit pas de la retrouver. Ne laissez pas les aliments périssables plus de 2 heures à température ambiante, ou 1 heure au-dessus de 32 °C. Contient des amandes ; granola et purée peuvent contenir d’autres fruits à coque, gluten, soja ou lait selon la marque. Vérifiez les étiquettes. Des graines adaptées peuvent remplacer les amandes et des flocons grillés prêts à consommer le granola, mais la nutrition change. Ne remplacez pas l’açaí par un autre fruit tout en gardant le même nom. L’estimation utilise une purée commerciale sans sucre et un granola générique USDA ; l’étiquette réelle peut différer.","seo":{"title":"Bol d’açaí à la banane et au granola, étape par étape","description":"Préparez deux bols d’açaí épais avec banane congelée, fraises, granola et amandes. Quantités proposées, congélation incluse et nutrition estimée.","image_alt":"Deux bols de crème d’açaí violette épaisse garnis en bandes de banane, fraises, granola et amandes effilées","image_variants":["/recetas/acai-bowl/portada-1x1.webp","/recetas/acai-bowl/portada-4x3.webp","/recetas/acai-bowl/portada-16x9.webp"],"faq":[{"q":"Quel açaí choisir ?","a":"Prenez 200 g de purée congelée sans sucre, prête à consommer selon l’étiquette. Sorbet, poudre et mélanges sucrés diffèrent par leur composition et leur texture. Les chiffres nutritionnels utilisent une référence commerciale USDA."},{"q":"Pourquoi la base est-elle liquide ou difficile à mixer ?","a":"La banane doit être congelée et l’açaí seulement légèrement ramolli. On propose 60 g d’eau pour toute la base ; davantage la dilue. Utilisez un blender adapté aux fruits congelés, sans forcer le moteur. Éteignez et débranchez avant de rabattre la préparation ; laissez ramollir un peu si nécessaire."},{"q":"Combien de temps faut-il et peut-on conserver la base ?","a":"On estime 135 minutes :120 pour congeler 160 g de banane et 15 de préparation. Avec la banane déjà congelée, le montage est estimé à 15 minutes. Servez les deux bols aussitôt. Une base restante couverte peut être gardée à 4 °C ou moins et consommée sous 24 heures, proposition domestique non testée ; garnitures à part."}]},"content_html":"<p>L’açaí congelé sans sucre et la banane congelée forment une base à manger à la cuillère, garnie de fraises, de granola et d’amandes. Deux bols et 135 minutes sont proposés, congélation préalable comprise. Formule, texture et durées restent à tester en cuisine.</p><p>Quantités et texture proposées, sans essai en cuisine. Choisissez une purée d’açaí congelée sans sucre, prête à consommer selon l’étiquette ; sorbet, poudre, boisson ou mélange sucré au guaraná ne sont pas équivalents. La banane apporte la douceur ; ni miel ni sirop ne sont ajoutés. Le bol n’est pas présenté comme une détox, un produit amaigrissant ou un traitement. Rincez les fruits sous l’eau courante avant de les éplucher ou couper, sans savon. Gardez la purée congelée jusqu’à la préparation. Suivez le manuel du blender et éteignez puis débranchez avant de toucher l’intérieur. Servez aussitôt. À titre de proposition domestique non testée, conservez seulement la base restante couverte à 4 °C ou moins et consommez-la sous 24 heures ; gardez les garnitures sèches à part. La texture se ramollit au froid ; une nouvelle congélation ne garantit pas de la retrouver. Ne laissez pas les aliments périssables plus de 2 heures à température ambiante, ou 1 heure au-dessus de 32 °C. Contient des amandes ; granola et purée peuvent contenir d’autres fruits à coque, gluten, soja ou lait selon la marque. Vérifiez les étiquettes. Des graines adaptées peuvent remplacer les amandes et des flocons grillés prêts à consommer le granola, mais la nutrition change. Ne remplacez pas l’açaí par un autre fruit tout en gardant le même nom. L’estimation utilise une purée commerciale sans sucre et un granola générique USDA ; l’étiquette réelle peut différer.</p>"},{"id":"b7e3e8a4-7df5-5355-891a-f93f56c8598c","recipe_group_id":"b6b4397e-f51a-4c05-bf7a-fa285432829b","slug":"ciotola-di-acai","public_path":"/it/ciotola-di-acai","source_url":"https://manualdecocina.com/it/ciotola-di-acai/","language":"it","title":"Bowl di açaí con banana, fragole e granola","excerpt":"Crema densa di açaí e banana congelata con frutta, granola e mandorle pesate: due ciotole proposte e valori nutrizionali stimati.","summary":"Açaí congelato senza zucchero e banana congelata formano una base da mangiare al cucchiaio, con fragole, granola e mandorle. Si propongono due ciotole e 135 minuti, compreso il congelamento preliminare della banana. Formula, consistenza e tempi devono ancora essere provati in cucina.","category":"Dolci","category_slug":"postres","difficulty":"Facile","course":"Colazione o dessert","cuisine":"Ispirazione brasiliana","prep_time_minutes":15,"cook_time_minutes":0,"total_time_minutes":135,"servings":2,"ingredients":[{"name":"purea di açaí congelata senza zucchero, pronta al consumo secondo l’etichetta","amount":"200","unit":"g","group":"Base"},{"name":"banana matura sbucciata da congelare","amount":"160","unit":"g","group":"Base"},{"name":"acqua potabile fredda","amount":"60","unit":"g","group":"Base"},{"name":"banana matura fresca sbucciata","amount":"60","unit":"g","group":"Guarnizione"},{"name":"fragole fresche senza picciolo","amount":"100","unit":"g","group":"Guarnizione"},{"name":"granola pronta da mangiare","amount":"40","unit":"g","group":"Guarnizione"},{"name":"mandorle naturali a lamelle","amount":"20","unit":"g","group":"Guarnizione"}],"steps":[{"title":"Congela la banana della base","content":"Lava le mani e sciacqua la banana prima di sbucciarla. Pesa 160 g di polpa matura e tagliala a rondelle di 1 cm. Disponile separate su una teglia pulita e congela a−18 °C o meno per circa 120 minuti, finché sono dure; prolunga se necessario e annota il tempo effettivo. Tieni separata la banana fresca per la guarnizione. Questi 120 minuti rientrano nei 135 minuti totali proposti. Se i 160 g sono già congelati, il montaggio è stimato in 15 minuti.","image_url":"/recetas/acai-bowl/paso-01.webp","image_alt":"Bowl di açaí con banana, fragole e granola: Congela la banana della base"},{"title":"Prepara guarnizione e attrezzatura","content":"Mentre la banana termina di congelarsi, sciacqua le fragole sotto acqua corrente senza sapone, asciugale, elimina i piccioli e pesa 100 g; tagliale a fettine. Sbuccia e taglia 60 g di banana fresca, poi pesa 40 g di granola pronta da mangiare e 20 g di mandorle a lamelle. Misura 60 g di acqua potabile fredda. Prepara due ciotole da circa 400 ml e un frullatore adatto alla frutta congelata secondo il manuale. Conserva al freddo la frutta tagliata fino al montaggio.","image_url":"/recetas/acai-bowl/paso-02.webp","image_alt":"Bowl di açaí con banana, fragole e granola: Prepara guarnizione e attrezzatura"},{"title":"Spezza la purea di açaí congelata","content":"Verifica che la purea sia senza zucchero e pronta al consumo secondo la confezione; questa ricetta non sostituisce una cottura prescritta dall’etichetta. Estrai 200 g dal congelatore appena prima di frullare. Piega delicatamente le buste chiuse per spezzare la purea oppure fai scorrere acqua all’esterno per circa 20 secondi, per staccarla senza scongelarla del tutto. Asciuga la confezione, aprila nel punto indicato e versa i pezzi in una ciotola pulita. Usa coltello o forbici con cautela, tagliando lontano dalla mano ed evitando frammenti di plastica nel cibo.","image_url":"/recetas/acai-bowl/paso-03.webp","image_alt":"Bowl di açaí con banana, fragole e granola: Spezza la purea di açaí congelata"},{"title":"Frulla una base densa","content":"Metti nel recipiente prima i 60 g di acqua, poi i 160 g di banana congelata e i 200 g di açaí a pezzi, rispettando manuale e capacità del frullatore. Chiudi il coperchio e lavora a impulsi brevi, per circa 1 minuto complessivo, fino a ottenere una crema viola densa senza grossi pezzi. Spegni e stacca la spina prima di raccogliere il composto con la spatola; mai introdurre mani o utensili con le lame in movimento. Non forzare il motore: se non riesce a muoverlo, lascia ammorbidire brevemente. Altra acqua cambia consistenza e peso di riferimento.","image_url":"/recetas/acai-bowl/paso-04.webp","image_alt":"Bowl di açaí con banana, fragole e granola: Frulla una base densa"},{"title":"Dividi la crema in due ciotole","content":"Con le lame ferme, dividi tutta la base fra le due ciotole, circa 210 g ciascuna prima della guarnizione, secondo quanto recuperato dal recipiente. Livella delicatamente con un cucchiaio. La crema deve sostenere la frutta e potersi mangiare al cucchiaio. Se è troppo liquida, raffreddala brevemente nel congelatore e annota il tempo aggiuntivo. Non aggiungere ghiaccio per nascondere un eccesso d’acqua.","image_url":"/recetas/acai-bowl/paso-05.webp","image_alt":"Bowl di açaí con banana, fragole e granola: Dividi la crema in due ciotole"},{"title":"Guarnisci e servi subito","content":"Aggiungi a ogni ciotola 30 g di banana fresca,50 g di fragole,20 g di granola e 10 g di mandorle a lamelle. Disponi a strisce lasciando visibile parte della base viola. Servi immediatamente. Si propongono 2 ciotole da circa 320 g, con 15 minuti di lavoro e 120 di congelamento preliminare, senza cottura. Quantità, consistenza, tempi e resa sono stimati e da provare in cucina. Le calorie comprendono tutta la guarnizione indicata.","image_url":"/recetas/acai-bowl/portada.webp","image_alt":"Bowl di açaí con banana, fragole e granola: Guarnisci e servi subito"}],"nutrition":{"calories":339.6,"protein_g":7.4,"carbs_g":45.9,"fat_g":15.4,"saturated_fat_g":2.3,"fiber_g":9.9,"sugar_g":20.3,"sodium_mg":18,"estimated":true,"source":"USDA FoodData Central — SR Legacy / Branded","source_url":"https://fdc.nal.usda.gov/download-datasets/","inputs":[{"ingredient":"purea di açaí congelata senza zucchero, pronta al consumo secondo l’etichetta","edible_grams":200,"fdc_id":2653289,"fdc_description":"ZERO SUGAR PURE UNSWEETENED AA BERRY SUPERFRUIT PACKS, AA BERRY","per_100g":{"calories":70,"protein_g":1,"carbs_g":4,"fat_g":5,"saturated_fat_g":1,"fiber_g":3,"sugar_g":0,"sodium_mg":10},"source_url":"https://fdc.nal.usda.gov/food-details/2653289/nutrients"},{"ingredient":"banana matura sbucciata da congelare","edible_grams":160,"fdc_id":173944,"fdc_description":"Bananas, raw","per_100g":{"calories":89,"protein_g":1.09,"carbs_g":22.8,"fat_g":0.33,"saturated_fat_g":0.112,"fiber_g":2.6,"sugar_g":12.2,"sodium_mg":1},"source_url":"https://fdc.nal.usda.gov/food-details/173944/nutrients"},{"ingredient":"acqua potabile fredda","edible_grams":60,"fdc_id":173647,"fdc_description":"Beverages, water, tap, drinking","per_100g":{"calories":0,"protein_g":0,"carbs_g":0,"fat_g":0,"saturated_fat_g":0,"fiber_g":0,"sugar_g":0,"sodium_mg":4},"source_url":"https://fdc.nal.usda.gov/food-details/173647/nutrients"},{"ingredient":"banana matura fresca sbucciata","edible_grams":60,"fdc_id":173944,"fdc_description":"Bananas, raw","per_100g":{"calories":89,"protein_g":1.09,"carbs_g":22.8,"fat_g":0.33,"saturated_fat_g":0.112,"fiber_g":2.6,"sugar_g":12.2,"sodium_mg":1},"source_url":"https://fdc.nal.usda.gov/food-details/173944/nutrients"},{"ingredient":"fragole fresche senza picciolo","edible_grams":100,"fdc_id":167762,"fdc_description":"Strawberries, raw","per_100g":{"calories":32,"protein_g":0.67,"carbs_g":7.68,"fat_g":0.3,"saturated_fat_g":0.015,"fiber_g":2,"sugar_g":4.89,"sodium_mg":1},"source_url":"https://fdc.nal.usda.gov/food-details/167762/nutrients"},{"ingredient":"granola pronta da mangiare","edible_grams":40,"fdc_id":171646,"fdc_description":"Cereals ready-to-eat, granola, homemade","per_100g":{"calories":489,"protein_g":13.7,"carbs_g":53.9,"fat_g":24.3,"saturated_fat_g":3.96,"fiber_g":8.9,"sugar_g":19.8,"sodium_mg":26},"source_url":"https://fdc.nal.usda.gov/food-details/171646/nutrients"},{"ingredient":"mandorle naturali a lamelle","edible_grams":20,"fdc_id":170567,"fdc_description":"Nuts, almonds","per_100g":{"calories":579,"protein_g":21.2,"carbs_g":21.6,"fat_g":49.9,"saturated_fat_g":3.8,"fiber_g":12.5,"sugar_g":4.35,"sodium_mg":1},"source_url":"https://fdc.nal.usda.gov/food-details/170567/nutrients"}],"serving_size":"Una ciotola;2 porzioni proposte da circa 320 g, peso finale non misurato","method":"Moltiplica sette pesi commestibili per gli otto valori USDA per 100 g, somma e dividi per 2. Banana della base e della guarnizione calcolate separatamente con la stessa scheda. Sono inclusi tutti i 60 g d’acqua, granola e mandorle, senza perdite inventate per congelamento o frullatura.","note":"Stima basata sugli ingredienti, non analisi di laboratorio né prova in cucina. Purea commerciale senza zucchero rappresentata da FDC 2653289,Sambazon,pubblicata 2023-10-26; non vale per tutte le marche, polveri, bevande o sorbetti. Granola casalinga generica FDC 171646 come riferimento: zuccheri, sodio e grassi dipendono dall’etichetta. Acqua potabile FDC 173647, minerali variabili. Tutti gli otto valori sono presenti; le assenze non vengono sostituite con zero."},"image_url":"/recetas/acai-bowl/portada.webp","gallery":[{"url":"/recetas/acai-bowl/portada.webp","alt":"Due ciotole di crema viola densa di açaí con strisce di banana, fragole, granola e mandorle a lamelle"}],"published":true,"editorial_status":"published","keywords":["bowl di açaí","açaí con banana","açaí con granola"],"notes":"Quantità e consistenza proposte, senza prova in cucina. Usa purea di açaí congelata senza zucchero, indicata come pronta al consumo; sorbetto, polvere, bevande o miscele zuccherate con guaranà non sono equivalenti. La banana dà dolcezza; non si aggiungono miele o sciroppo. La bowl non è presentata come detox, dimagrante o trattamento. Sciacqua la frutta sotto acqua corrente prima di sbucciarla o tagliarla, senza sapone. Mantieni la purea congelata fino alla preparazione. Rispetta il manuale del frullatore e spegni e stacca la spina prima di toccarne l’interno. Servi subito. Come proposta domestica non sperimentata, conserva solo la base avanzata coperta a 4 °C o meno e consumala entro 24 ore, tenendo separati gli ingredienti secchi della guarnizione. La consistenza si ammorbidisce in frigorifero; ricongelarla non garantisce lo stesso risultato. Non lasciare alimenti deperibili a temperatura ambiente oltre 2 ore, oppure 1 ora se supera 32 °C. Contiene mandorle; granola e purea possono contenere altra frutta a guscio, glutine, soia o latte secondo la marca. Controlla le etichette. Semi adatti ai commensali possono sostituire le mandorle e fiocchi tostati pronti al consumo la granola, ma i valori nutrizionali cambiano. Non sostituire l’açaí con altro frutto mantenendo lo stesso nome. La stima usa una purea commerciale senza zucchero e granola generica USDA; l’etichetta reale può differire.","seo":{"title":"Bowl di açaí con banana e granola passo dopo passo","description":"Prepara due bowl dense di açaí con banana congelata, fragole, granola e mandorle. Quantità proposte, congelamento incluso e nutrizione stimata.","image_alt":"Due ciotole di crema viola densa di açaí con strisce di banana, fragole, granola e mandorle a lamelle","image_variants":["/recetas/acai-bowl/portada-1x1.webp","/recetas/acai-bowl/portada-4x3.webp","/recetas/acai-bowl/portada-16x9.webp"],"faq":[{"q":"Quale açaí devo scegliere?","a":"Usa 200 g di purea congelata senza zucchero e pronta al consumo secondo l’etichetta. Sorbetto, polvere e miscele zuccherate hanno composizione e consistenza diverse. La nutrizione stimata usa un alimento commerciale USDA di riferimento."},{"q":"Perché è liquida o il frullatore non gira?","a":"La banana deve essere congelata e l’açaí solo leggermente ammorbidito. Si propongono 60 g di acqua per tutta la base: altra acqua la diluisce. Usa un apparecchio adatto ai congelati, senza forzare il motore. Spegni e stacca la spina prima di usare la spatola; lascia ammorbidire se necessario."},{"q":"Quanto tempo serve e posso conservarla?","a":"Si stimano 135 minuti:120 per congelare 160 g di banana e 15 di lavoro. Con banana già congelata, il montaggio è stimato in 15 minuti. Servi subito entrambe le ciotole. Base avanzata coperta a 4 °C o meno, da consumare entro 24 ore come proposta domestica non testata, con guarnizione separata."}]},"content_html":"<p>Açaí congelato senza zucchero e banana congelata formano una base da mangiare al cucchiaio, con fragole, granola e mandorle. Si propongono due ciotole e 135 minuti, compreso il congelamento preliminare della banana. Formula, consistenza e tempi devono ancora essere provati in cucina.</p><p>Quantità e consistenza proposte, senza prova in cucina. Usa purea di açaí congelata senza zucchero, indicata come pronta al consumo; sorbetto, polvere, bevande o miscele zuccherate con guaranà non sono equivalenti. La banana dà dolcezza; non si aggiungono miele o sciroppo. La bowl non è presentata come detox, dimagrante o trattamento. Sciacqua la frutta sotto acqua corrente prima di sbucciarla o tagliarla, senza sapone. Mantieni la purea congelata fino alla preparazione. Rispetta il manuale del frullatore e spegni e stacca la spina prima di toccarne l’interno. Servi subito. Come proposta domestica non sperimentata, conserva solo la base avanzata coperta a 4 °C o meno e consumala entro 24 ore, tenendo separati gli ingredienti secchi della guarnizione. La consistenza si ammorbidisce in frigorifero; ricongelarla non garantisce lo stesso risultato. Non lasciare alimenti deperibili a temperatura ambiente oltre 2 ore, oppure 1 ora se supera 32 °C. Contiene mandorle; granola e purea possono contenere altra frutta a guscio, glutine, soia o latte secondo la marca. Controlla le etichette. Semi adatti ai commensali possono sostituire le mandorle e fiocchi tostati pronti al consumo la granola, ma i valori nutrizionali cambiano. Non sostituire l’açaí con altro frutto mantenendo lo stesso nome. La stima usa una purea commerciale senza zucchero e granola generica USDA; l’etichetta reale può differire.</p>"},{"id":"08e76f22-edf5-514c-8fa5-d90531fcdcf0","recipe_group_id":"b6b4397e-f51a-4c05-bf7a-fa285432829b","slug":"アサイーボウル","public_path":"/ja/アサイーボウル","source_url":"https://manualdecocina.com/ja/アサイーボウル/","language":"ja","title":"バナナといちご、グラノーラのアサイーボウル","excerpt":"濃厚なアサイーと冷凍バナナに、量を決めたいちご、グラノーラ、アーモンドを添えます。提案の分量は2人分で、栄養値は材料からの推定です。","summary":"砂糖不使用の冷凍アサイーピューレと冷凍バナナを、スプーンで食べる濃厚なベースにします。いちご、グラノーラ、アーモンドを添える2杯分の提案で、バナナの事前冷凍を含め135分。配合、食感、時間は調理試験で未確認です。","category":"デザート","category_slug":"postres","difficulty":"簡単","course":"朝食またはデザート","cuisine":"ブラジル風","prep_time_minutes":15,"cook_time_minutes":0,"total_time_minutes":135,"servings":2,"ingredients":[{"name":"砂糖不使用の冷凍アサイーピューレ、そのまま食べられる表示のもの","amount":"200","unit":"g","group":"ベース"},{"name":"冷凍用の熟したバナナ、皮を除いた重量","amount":"160","unit":"g","group":"ベース"},{"name":"冷たい飲用水","amount":"60","unit":"g","group":"ベース"},{"name":"熟した生のバナナ、皮を除いた重量","amount":"60","unit":"g","group":"トッピング"},{"name":"生のいちご、へたを除いた重量","amount":"100","unit":"g","group":"トッピング"},{"name":"そのまま食べられるグラノーラ","amount":"40","unit":"g","group":"トッピング"},{"name":"無調味のスライスアーモンド","amount":"20","unit":"g","group":"トッピング"}],"steps":[{"title":"ベース用のバナナを冷凍する","content":"手を洗い、バナナは皮をむく前に流水ですすぎます。熟した果肉160 gを量り、厚さ1 cmの輪切りにします。清潔なトレーに重ならないように並べ、−18 °C以下で120分を目安に、硬くなるまで冷凍します。硬くなければ延長し、実際の時間を記録します。トッピング用の生バナナは別にしておきます。この120分は提案の合計135分に含まれます。160 gがすでに冷凍済みなら、組み立て作業は15分が目安です。","image_url":"/recetas/acai-bowl/paso-01.webp","image_alt":"バナナといちご、グラノーラのアサイーボウル: ベース用のバナナを冷凍する"},{"title":"トッピングと道具を準備する","content":"バナナの冷凍が終わる間に、いちごを石けんを使わず流水ですすぎ、水気を取り、へたを除いて100 gを量り薄切りにします。生のバナナ60 gをむいて切り、そのまま食べられるグラノーラ40 gとスライスアーモンド20 gを量ります。冷たい飲用水60 gを用意します。約400 mlの器を二つと、説明書で冷凍果物に対応するミキサーを準備します。切った果物は盛り付けまで冷やしておきます。","image_url":"/recetas/acai-bowl/paso-02.webp","image_alt":"バナナといちご、グラノーラのアサイーボウル: トッピングと道具を準備する"},{"title":"冷凍アサイーピューレを割る","content":"砂糖不使用で、そのまま食べられる表示を確認します。このレシピは表示で指定された加熱の代わりにはなりません。攪拌する直前に200 gを冷凍庫から出します。袋を閉じたまま軽く曲げて中身を割るか、袋の外側に約20秒水を流して中身を外しやすくします。完全には解凍しません。袋を拭き、指定箇所で開け、清潔な器へ固い欠片を出します。包丁やはさみは手から離れる向きで慎重に使い、食品に袋の切れ端が混ざらないようにします。","image_url":"/recetas/acai-bowl/paso-03.webp","image_alt":"バナナといちご、グラノーラのアサイーボウル: 冷凍アサイーピューレを割る"},{"title":"濃厚なベースを攪拌する","content":"ミキサーにまず水60 g、次に冷凍バナナ160 gと砕いたアサイー200 gを入れ、説明書と容量制限を守ります。ふたを閉め、短く断続的に動かし、合計約1分で大きな塊のない濃厚な紫色のクリームにします。へらで下へ寄せるときは停止して電源プラグを抜きます。刃が動く間は手や道具を入れません。モーターを無理に回さず、動かない場合は数分柔らかくします。水を追加すると食感と基準重量が変わります。","image_url":"/recetas/acai-bowl/paso-04.webp","image_alt":"バナナといちご、グラノーラのアサイーボウル: 濃厚なベースを攪拌する"},{"title":"ベースを2つの器に分ける","content":"刃が完全に止まったら、ベースをすべて二つの器に分けます。トッピング前は各約210 gが目安ですが、ミキサーから取り出せた量によります。スプーンで軽く表面を整えます。果物を表面で支え、スプーンで食べられる硬さが目標です。ゆるい場合は冷凍庫で数分冷やし、追加時間を記録します。水の入れすぎを隠すために氷を加えないでください。","image_url":"/recetas/acai-bowl/paso-05.webp","image_alt":"バナナといちご、グラノーラのアサイーボウル: ベースを2つの器に分ける"},{"title":"トッピングしてすぐ食べる","content":"各器に生バナナ30 g、いちご50 g、グラノーラ20 g、スライスアーモンド10 gをのせます。紫色のベースが見えるように帯状に並べます。すぐに提供します。提案の仕上がりは約320 gの器2杯で、作業15分と事前冷凍120分を見込み、加熱調理はしません。分量、食感、時間、出来上がり量は推定で調理試験待ちです。カロリーには記載したトッピングをすべて含みます。","image_url":"/recetas/acai-bowl/portada.webp","image_alt":"バナナといちご、グラノーラのアサイーボウル: トッピングしてすぐ食べる"}],"nutrition":{"calories":339.6,"protein_g":7.4,"carbs_g":45.9,"fat_g":15.4,"saturated_fat_g":2.3,"fiber_g":9.9,"sugar_g":20.3,"sodium_mg":18,"estimated":true,"source":"USDA FoodData Central — SR Legacy / Branded","source_url":"https://fdc.nal.usda.gov/download-datasets/","inputs":[{"ingredient":"砂糖不使用の冷凍アサイーピューレ、そのまま食べられる表示のもの","edible_grams":200,"fdc_id":2653289,"fdc_description":"ZERO SUGAR PURE UNSWEETENED AA BERRY SUPERFRUIT PACKS, AA BERRY","per_100g":{"calories":70,"protein_g":1,"carbs_g":4,"fat_g":5,"saturated_fat_g":1,"fiber_g":3,"sugar_g":0,"sodium_mg":10},"source_url":"https://fdc.nal.usda.gov/food-details/2653289/nutrients"},{"ingredient":"冷凍用の熟したバナナ、皮を除いた重量","edible_grams":160,"fdc_id":173944,"fdc_description":"Bananas, raw","per_100g":{"calories":89,"protein_g":1.09,"carbs_g":22.8,"fat_g":0.33,"saturated_fat_g":0.112,"fiber_g":2.6,"sugar_g":12.2,"sodium_mg":1},"source_url":"https://fdc.nal.usda.gov/food-details/173944/nutrients"},{"ingredient":"冷たい飲用水","edible_grams":60,"fdc_id":173647,"fdc_description":"Beverages, water, tap, drinking","per_100g":{"calories":0,"protein_g":0,"carbs_g":0,"fat_g":0,"saturated_fat_g":0,"fiber_g":0,"sugar_g":0,"sodium_mg":4},"source_url":"https://fdc.nal.usda.gov/food-details/173647/nutrients"},{"ingredient":"熟した生のバナナ、皮を除いた重量","edible_grams":60,"fdc_id":173944,"fdc_description":"Bananas, raw","per_100g":{"calories":89,"protein_g":1.09,"carbs_g":22.8,"fat_g":0.33,"saturated_fat_g":0.112,"fiber_g":2.6,"sugar_g":12.2,"sodium_mg":1},"source_url":"https://fdc.nal.usda.gov/food-details/173944/nutrients"},{"ingredient":"生のいちご、へたを除いた重量","edible_grams":100,"fdc_id":167762,"fdc_description":"Strawberries, raw","per_100g":{"calories":32,"protein_g":0.67,"carbs_g":7.68,"fat_g":0.3,"saturated_fat_g":0.015,"fiber_g":2,"sugar_g":4.89,"sodium_mg":1},"source_url":"https://fdc.nal.usda.gov/food-details/167762/nutrients"},{"ingredient":"そのまま食べられるグラノーラ","edible_grams":40,"fdc_id":171646,"fdc_description":"Cereals ready-to-eat, granola, homemade","per_100g":{"calories":489,"protein_g":13.7,"carbs_g":53.9,"fat_g":24.3,"saturated_fat_g":3.96,"fiber_g":8.9,"sugar_g":19.8,"sodium_mg":26},"source_url":"https://fdc.nal.usda.gov/food-details/171646/nutrients"},{"ingredient":"無調味のスライスアーモンド","edible_grams":20,"fdc_id":170567,"fdc_description":"Nuts, almonds","per_100g":{"calories":579,"protein_g":21.2,"carbs_g":21.6,"fat_g":49.9,"saturated_fat_g":3.8,"fiber_g":12.5,"sugar_g":4.35,"sodium_mg":1},"source_url":"https://fdc.nal.usda.gov/food-details/170567/nutrients"}],"serving_size":"1杯分。約320 gを2人分とする提案で、仕上がり重量は未測定","method":"食べられる部分の7つの材料重量に、それぞれ100 g当たりのUSDAの8項目の値を掛け、合計を2で割ります。ベースとトッピングのバナナは同じ記録で別々に計算します。水60 g、グラノーラ、アーモンドをすべて含み、冷凍や攪拌での損失は架空に設定しません。","note":"材料による推定で、実験室分析や調理試験ではありません。市販の砂糖不使用ピューレはSambazonのFDC2653289、公開日2023-10-26を参照し、全製品、粉末、飲料、シャーベットを代表しません。グラノーラは一般的な自家製のFDC171646を参照し、糖、ナトリウム、脂質は表示で変わります。飲用水はFDC173647を使用しミネラル量は変動します。8項目はすべて記録にあり、欠損をゼロで埋めません。"},"image_url":"/recetas/acai-bowl/portada.webp","gallery":[{"url":"/recetas/acai-bowl/portada.webp","alt":"紫色の濃厚なアサイーに、バナナ、いちご、グラノーラ、スライスアーモンドを帯状にのせた2つの器"}],"published":true,"editorial_status":"published","keywords":["アサイーボウル","バナナ入りアサイー","アサイーとグラノーラ"],"notes":"分量と食感は提案で、調理試験は行っていません。砂糖不使用の冷凍アサイーピューレで、そのまま食べられる表示の製品を使います。シャーベット、粉末、飲料、砂糖とガラナを加えた混合品は同じ材料ではありません。甘みはバナナから得て、はちみつやシロップは加えません。デトックス、減量用、治療用として紹介しません。果物は皮をむく、または切る前に流水ですすぎ、石けんは使いません。ピューレは準備直前まで冷凍を保ちます。ミキサーの説明書を守り、内部に触る前に停止してプラグを抜きます。出来たらすぐ食べます。保存試験をしていない家庭向けの提案として、残ったベースのみをふた付きで4 °C以下に冷蔵し24時間以内に食べ、乾いたトッピングは別に保管します。冷蔵中に食感はゆるくなり、再冷凍で元に戻る保証はありません。傷みやすい食品を室温で2時間以上、32 °Cを超える場合は1時間以上置かないでください。アーモンドを含みます。グラノーラやピューレは製品によりほかのナッツ、小麦などのグルテン、大豆、乳を含むことがあるため表示を確認します。食べる人に適した種子でアーモンドを、そのまま食べられる焙煎オーツでグラノーラを置き換える場合は栄養値が変わります。アサイーを別の果物に替えた料理を同じレシピ名で扱わないでください。栄養値はUSDAの砂糖不使用市販ピューレと一般的なグラノーラの記録で推定し、手元の製品表示とは異なる場合があります。","seo":{"title":"アサイーボウルの作り方｜バナナとグラノーラ","description":"冷凍バナナとアサイーの濃厚な2人分のボウルに、いちご、グラノーラ、アーモンドを添えます。提案の分量、冷凍時間、推定栄養値を掲載。","image_alt":"紫色の濃厚なアサイーに、バナナ、いちご、グラノーラ、スライスアーモンドを帯状にのせた2つの器","image_variants":["/recetas/acai-bowl/portada-1x1.webp","/recetas/acai-bowl/portada-4x3.webp","/recetas/acai-bowl/portada-16x9.webp"],"faq":[{"q":"どのアサイーを使いますか？","a":"砂糖不使用の冷凍ピューレ200 gで、そのまま食べられる表示のものを使います。シャーベット、粉末、加糖混合品では成分と食感が変わります。栄養値はUSDAの市販品の記録を参照した推定です。"},{"q":"ゆるくなる、またはミキサーが動かないのはなぜですか？","a":"バナナは冷凍し、アサイーは完全に解凍しないで使います。ベース全体の水は60 gを提案し、増やすとゆるくなります。冷凍果物対応の機器でモーターを無理に回さず、へらを使う前は停止してプラグを抜きます。機器に応じ少し柔らかくしてください。"},{"q":"所要時間と保存方法は？","a":"バナナ160 gを冷凍する120分と作業15分で、合計135分が目安です。バナナが冷凍済みなら作業は15分程度です。2杯ともすぐ食べるのがおすすめです。残ったベースはふたをして4 °C以下で冷蔵し24時間以内に食べ、トッピングは別にします。保存試験をしていない家庭向けの提案です。"}]},"content_html":"<p>砂糖不使用の冷凍アサイーピューレと冷凍バナナを、スプーンで食べる濃厚なベースにします。いちご、グラノーラ、アーモンドを添える2杯分の提案で、バナナの事前冷凍を含め135分。配合、食感、時間は調理試験で未確認です。</p><p>分量と食感は提案で、調理試験は行っていません。砂糖不使用の冷凍アサイーピューレで、そのまま食べられる表示の製品を使います。シャーベット、粉末、飲料、砂糖とガラナを加えた混合品は同じ材料ではありません。甘みはバナナから得て、はちみつやシロップは加えません。デトックス、減量用、治療用として紹介しません。果物は皮をむく、または切る前に流水ですすぎ、石けんは使いません。ピューレは準備直前まで冷凍を保ちます。ミキサーの説明書を守り、内部に触る前に停止してプラグを抜きます。出来たらすぐ食べます。保存試験をしていない家庭向けの提案として、残ったベースのみをふた付きで4 °C以下に冷蔵し24時間以内に食べ、乾いたトッピングは別に保管します。冷蔵中に食感はゆるくなり、再冷凍で元に戻る保証はありません。傷みやすい食品を室温で2時間以上、32 °Cを超える場合は1時間以上置かないでください。アーモンドを含みます。グラノーラやピューレは製品によりほかのナッツ、小麦などのグルテン、大豆、乳を含むことがあるため表示を確認します。食べる人に適した種子でアーモンドを、そのまま食べられる焙煎オーツでグラノーラを置き換える場合は栄養値が変わります。アサイーを別の果物に替えた料理を同じレシピ名で扱わないでください。栄養値はUSDAの砂糖不使用市販ピューレと一般的なグラノーラの記録で推定し、手元の製品表示とは異なる場合があります。</p>"},{"id":"af0dad96-4162-5081-bded-f173c37071f6","recipe_group_id":"b6b4397e-f51a-4c05-bf7a-fa285432829b","slug":"tigela-de-acai","public_path":"/pt/tigela-de-acai","source_url":null,"language":"pt","title":"Açaí na tigela com banana, morango e granola","excerpt":"Creme espesso de açaí e banana congelada com frutas, granola e amêndoas pesadas: duas tigelas propostas e nutrição estimada por porção.","summary":"Polpa de açaí congelada sem açúcar e banana congelada formam uma base para comer de colher, com morango, granola e amêndoas. A proposta rende duas tigelas em 135 minutos, incluindo o congelamento prévio da banana. Fórmula, textura e tempos aguardam teste de cozinha.","category":"Sobremesas","category_slug":"postres","difficulty":"Fácil","course":"Café da manhã ou sobremesa","cuisine":"Inspiração brasileira","prep_time_minutes":15,"cook_time_minutes":0,"total_time_minutes":135,"servings":2,"ingredients":[{"name":"polpa de açaí congelada sem açúcar, pronta para consumo conforme o rótulo","amount":"200","unit":"g","group":"Base"},{"name":"banana madura sem casca, para congelar","amount":"160","unit":"g","group":"Base"},{"name":"água potável fria","amount":"60","unit":"g","group":"Base"},{"name":"banana madura fresca sem casca","amount":"60","unit":"g","group":"Cobertura"},{"name":"morangos frescos sem cabinho","amount":"100","unit":"g","group":"Cobertura"},{"name":"granola pronta para comer","amount":"40","unit":"g","group":"Cobertura"},{"name":"amêndoas naturais laminadas","amount":"20","unit":"g","group":"Cobertura"}],"steps":[{"title":"Congele a banana da base","content":"Lave as mãos e enxágue a banana antes de descascar. Pese 160 g de polpa madura e corte em rodelas de 1 cm. Espalhe separadas em uma assadeira limpa e congele a−18 °C ou menos por cerca de 120 minutos, até endurecer; prolongue se necessário e registre o tempo real. Mantenha separada a banana fresca da cobertura. Esses 120 minutos fazem parte dos 135 minutos totais propostos. Se os 160 g já estiverem congelados, o preparo é estimado em 15 minutos.","image_url":"/recetas/acai-bowl/paso-01.webp","image_alt":"Açaí na tigela com banana, morango e granola: Congele a banana da base"},{"title":"Prepare a cobertura e os utensílios","content":"Enquanto a banana termina de congelar, enxágue os morangos sob água corrente, sem sabão, seque, retire os cabinhos e pese 100 g; corte em fatias. Descasque e corte 60 g de banana fresca e pese 40 g de granola pronta para comer e 20 g de amêndoas laminadas. Meça 60 g de água potável fria. Separe duas tigelas de cerca de 400 ml e um liquidificador adequado para frutas congeladas segundo o manual. Mantenha as frutas cortadas refrigeradas até montar.","image_url":"/recetas/acai-bowl/paso-02.webp","image_alt":"Açaí na tigela com banana, morango e granola: Prepare a cobertura e os utensílios"},{"title":"Quebre a polpa de açaí congelada","content":"Confira se a polpa é sem açúcar e pronta para consumo conforme a embalagem; esta receita não substitui um cozimento exigido pelo rótulo. Retire 200 g do congelador pouco antes de bater. Flexione os pacotes fechados para quebrar a polpa ou passe água pela parte externa por cerca de 20 segundos, para soltá-la sem descongelar completamente. Seque a embalagem, abra no ponto indicado e coloque os pedaços em uma tigela limpa. Use faca ou tesoura com cuidado, cortando longe da mão e evitando fragmentos de plástico na comida.","image_url":"/recetas/acai-bowl/paso-03.webp","image_alt":"Açaí na tigela com banana, morango e granola: Quebre a polpa de açaí congelada"},{"title":"Bata uma base espessa","content":"Coloque no copo primeiro os 60 g de água, depois os 160 g de banana congelada e os 200 g de açaí em pedaços, respeitando o manual e a capacidade do liquidificador. Feche a tampa e bata em pulsos curtos, por aproximadamente 1 minuto no total, até obter um creme roxo espesso sem pedaços grandes. Desligue e tire da tomada antes de baixar a mistura com a espátula; nunca coloque mãos ou utensílios perto das lâminas em movimento. Não force o motor: se não conseguir movimentar o creme, deixe amolecer por alguns minutos. Água adicional altera a textura e o peso de referência.","image_url":"/recetas/acai-bowl/paso-04.webp","image_alt":"Açaí na tigela com banana, morango e granola: Bata uma base espessa"},{"title":"Divida a base em duas tigelas","content":"Com as lâminas paradas, divida toda a base entre as duas tigelas, cerca de 210 g em cada uma antes da cobertura, conforme a quantidade recuperada do copo. Alise delicadamente com uma colher. O creme deve sustentar as frutas e ser comido de colher. Se ficar líquido demais, resfrie por alguns minutos no congelador e registre esse tempo extra. Não acrescente gelo para disfarçar água em excesso.","image_url":"/recetas/acai-bowl/paso-05.webp","image_alt":"Açaí na tigela com banana, morango e granola: Divida a base em duas tigelas"},{"title":"Coloque a cobertura e sirva na hora","content":"Em cada tigela, distribua 30 g de banana fresca,50 g de morango,20 g de granola e 10 g de amêndoas laminadas. Faça faixas deixando parte da base roxa à vista. Sirva imediatamente. A proposta rende 2 tigelas de cerca de 320 g, com 15 minutos de trabalho e 120 de congelamento prévio, sem cozimento. Quantidades, textura, tempos e rendimento são estimados e aguardam teste de cozinha. As calorias incluem toda a cobertura indicada.","image_url":"/recetas/acai-bowl/portada.webp","image_alt":"Açaí na tigela com banana, morango e granola: Coloque a cobertura e sirva na hora"}],"nutrition":{"calories":339.6,"protein_g":7.4,"carbs_g":45.9,"fat_g":15.4,"saturated_fat_g":2.3,"fiber_g":9.9,"sugar_g":20.3,"sodium_mg":18,"estimated":true,"source":"USDA FoodData Central — SR Legacy / Branded","source_url":"https://fdc.nal.usda.gov/download-datasets/","inputs":[{"ingredient":"polpa de açaí congelada sem açúcar, pronta para consumo conforme o rótulo","edible_grams":200,"fdc_id":2653289,"fdc_description":"ZERO SUGAR PURE UNSWEETENED AA BERRY SUPERFRUIT PACKS, AA BERRY","per_100g":{"calories":70,"protein_g":1,"carbs_g":4,"fat_g":5,"saturated_fat_g":1,"fiber_g":3,"sugar_g":0,"sodium_mg":10},"source_url":"https://fdc.nal.usda.gov/food-details/2653289/nutrients"},{"ingredient":"banana madura sem casca, para congelar","edible_grams":160,"fdc_id":173944,"fdc_description":"Bananas, raw","per_100g":{"calories":89,"protein_g":1.09,"carbs_g":22.8,"fat_g":0.33,"saturated_fat_g":0.112,"fiber_g":2.6,"sugar_g":12.2,"sodium_mg":1},"source_url":"https://fdc.nal.usda.gov/food-details/173944/nutrients"},{"ingredient":"água potável fria","edible_grams":60,"fdc_id":173647,"fdc_description":"Beverages, water, tap, drinking","per_100g":{"calories":0,"protein_g":0,"carbs_g":0,"fat_g":0,"saturated_fat_g":0,"fiber_g":0,"sugar_g":0,"sodium_mg":4},"source_url":"https://fdc.nal.usda.gov/food-details/173647/nutrients"},{"ingredient":"banana madura fresca sem casca","edible_grams":60,"fdc_id":173944,"fdc_description":"Bananas, raw","per_100g":{"calories":89,"protein_g":1.09,"carbs_g":22.8,"fat_g":0.33,"saturated_fat_g":0.112,"fiber_g":2.6,"sugar_g":12.2,"sodium_mg":1},"source_url":"https://fdc.nal.usda.gov/food-details/173944/nutrients"},{"ingredient":"morangos frescos sem cabinho","edible_grams":100,"fdc_id":167762,"fdc_description":"Strawberries, raw","per_100g":{"calories":32,"protein_g":0.67,"carbs_g":7.68,"fat_g":0.3,"saturated_fat_g":0.015,"fiber_g":2,"sugar_g":4.89,"sodium_mg":1},"source_url":"https://fdc.nal.usda.gov/food-details/167762/nutrients"},{"ingredient":"granola pronta para comer","edible_grams":40,"fdc_id":171646,"fdc_description":"Cereals ready-to-eat, granola, homemade","per_100g":{"calories":489,"protein_g":13.7,"carbs_g":53.9,"fat_g":24.3,"saturated_fat_g":3.96,"fiber_g":8.9,"sugar_g":19.8,"sodium_mg":26},"source_url":"https://fdc.nal.usda.gov/food-details/171646/nutrients"},{"ingredient":"amêndoas naturais laminadas","edible_grams":20,"fdc_id":170567,"fdc_description":"Nuts, almonds","per_100g":{"calories":579,"protein_g":21.2,"carbs_g":21.6,"fat_g":49.9,"saturated_fat_g":3.8,"fiber_g":12.5,"sugar_g":4.35,"sodium_mg":1},"source_url":"https://fdc.nal.usda.gov/food-details/170567/nutrients"}],"serving_size":"Uma tigela;2 porções propostas de cerca de 320 g, peso final não medido","method":"Multiplique sete quantidades comestíveis em gramas pelos oito valores USDA por 100 g, some e divida por 2. Banana da base e da cobertura calculadas separadamente com a mesma ficha. Inclui todos os 60 g de água, granola e amêndoas, sem inventar perdas ao congelar ou bater.","note":"Estimativa por ingredientes, sem análise laboratorial nem teste de cozinha. Polpa comercial sem açúcar modelada com FDC 2653289,Sambazon, publicada 2023-10-26; não representa todas as marcas, pós, bebidas ou sorbets. Granola caseira genérica FDC 171646 como referência: açúcar, sódio e gorduras variam por rótulo. Água potável FDC 173647, minerais variáveis. Os oito nutrientes estão presentes nas fichas; dados ausentes nunca são preenchidos com zero."},"image_url":"/recetas/acai-bowl/portada.webp","gallery":[{"url":"/recetas/acai-bowl/portada.webp","alt":"Duas tigelas de creme roxo espesso de açaí com faixas de banana, morango, granola e amêndoas laminadas"}],"published":true,"editorial_status":"published","keywords":["açaí na tigela","açaí com banana","açaí com granola"],"notes":"Quantidades e textura propostas, sem teste de cozinha. Use polpa de açaí congelada sem açúcar, pronta para consumo conforme o rótulo; sorbet, pó, bebida ou misturas com guaraná e açúcar não são equivalentes. A banana fornece doçura; não se acrescentam mel nem xarope. A tigela não é apresentada como detox, emagrecedora ou tratamento. Enxágue as frutas sob água corrente antes de descascar ou cortar, sem sabão. Mantenha a polpa congelada até preparar. Siga o manual do liquidificador e desligue e tire da tomada antes de tocar no interior. Sirva imediatamente. Como proposta doméstica não testada, guarde apenas a base restante tampada a 4 °C ou menos e consuma em 24 horas, mantendo a cobertura seca separada. A textura perde firmeza na geladeira; recongelar não garante recuperar o resultado. Não deixe alimentos perecíveis mais de 2 horas em temperatura ambiente, ou 1 hora se passar de 32 °C. Contém amêndoas; granola e polpa podem conter outras castanhas, glúten, soja ou leite, conforme a marca. Confira os rótulos. Sementes adequadas aos comensais podem substituir as amêndoas, ou flocos tostados prontos para comer podem substituir a granola, mas a nutrição muda. Não substitua açaí por outra fruta mantendo o mesmo nome. A estimativa usa uma polpa comercial sem açúcar e granola genérica USDA; o rótulo real pode ser diferente.","seo":{"title":"Açaí na tigela com banana e granola: passo a passo","description":"Prepare duas tigelas de açaí espesso com banana congelada, morango, granola e amêndoas. Quantidades propostas, congelamento incluído e nutrição estimada.","image_alt":"Duas tigelas de creme roxo espesso de açaí com faixas de banana, morango, granola e amêndoas laminadas","image_variants":["/recetas/acai-bowl/portada-1x1.webp","/recetas/acai-bowl/portada-4x3.webp","/recetas/acai-bowl/portada-16x9.webp"],"faq":[{"q":"Que açaí serve para esta receita?","a":"Use 200 g de polpa congelada sem açúcar, pronta para consumo conforme o rótulo. Sorbet, pó e misturas adoçadas têm composição e textura diferentes. A nutrição estimada usa uma referência comercial USDA."},{"q":"Por que fica líquido ou o liquidificador não consegue bater?","a":"A banana deve estar congelada e o açaí apenas levemente amolecido. A proposta usa 60 g de água para toda a base; mais água dilui o creme. Use um aparelho adequado para frutas congeladas e não force o motor. Desligue e tire da tomada antes de usar a espátula; deixe amolecer um pouco se o equipamento exigir."},{"q":"Quanto tempo leva e posso guardar?","a":"São estimados 135 minutos:120 para congelar 160 g de banana e 15 de trabalho. Com banana já congelada, a montagem é estimada em 15 minutos. Sirva as duas tigelas imediatamente. Uma base restante tampada pode ficar a 4 °C ou menos e ser consumida em 24 horas, como proposta doméstica sem teste, com a cobertura separada."}]},"content_html":"<p>Polpa de açaí congelada sem açúcar e banana congelada formam uma base para comer de colher, com morango, granola e amêndoas. A proposta rende duas tigelas em 135 minutos, incluindo o congelamento prévio da banana. Fórmula, textura e tempos aguardam teste de cozinha.</p><p>Quantidades e textura propostas, sem teste de cozinha. Use polpa de açaí congelada sem açúcar, pronta para consumo conforme o rótulo; sorbet, pó, bebida ou misturas com guaraná e açúcar não são equivalentes. A banana fornece doçura; não se acrescentam mel nem xarope. A tigela não é apresentada como detox, emagrecedora ou tratamento. Enxágue as frutas sob água corrente antes de descascar ou cortar, sem sabão. Mantenha a polpa congelada até preparar. Siga o manual do liquidificador e desligue e tire da tomada antes de tocar no interior. Sirva imediatamente. Como proposta doméstica não testada, guarde apenas a base restante tampada a 4 °C ou menos e consuma em 24 horas, mantendo a cobertura seca separada. A textura perde firmeza na geladeira; recongelar não garante recuperar o resultado. Não deixe alimentos perecíveis mais de 2 horas em temperatura ambiente, ou 1 hora se passar de 32 °C. Contém amêndoas; granola e polpa podem conter outras castanhas, glúten, soja ou leite, conforme a marca. Confira os rótulos. Sementes adequadas aos comensais podem substituir as amêndoas, ou flocos tostados prontos para comer podem substituir a granola, mas a nutrição muda. Não substitua açaí por outra fruta mantendo o mesmo nome. A estimativa usa uma polpa comercial sem açúcar e granola genérica USDA; o rótulo real pode ser diferente.</p>"}]$records$::jsonb;
 b constant jsonb := $before${"id":"c9b69094-9cd5-4b3c-b33b-a988f326b009","recipe_group_id":"b6b4397e-f51a-4c05-bf7a-fa285432829b","slug":"acai-bowl","public_path":"/acai-bowl","source_url":"https://manualdecocina.com/acai-bowl/","created_at":"2026-09-23 20:50:30.371317+00","published_at":"2026-09-23 20:50:30.371317+00","expected_row_md5":"634785a82e0d60ab3a622e80d6c6b74f"}$before$::jsonb;
